import { assemblyStackDepth } from './assemblyStackDepth';
import { assemblyDebugDepth } from './assemblyDebugDepth';

// Additional reasoning and independent traces for the assembly reading path.
// All live examples retain the course's 386-or-newer, BITS 16, real-mode contract.
const dive = (title, paragraphs, example, pitfall, transfer, flowchart) => ({
  title, paragraphs,
  example: { title: example[0], intro: example[1], steps: example[2].map(([title, explanation, state]) => ({ title, explanation, ...(state ? { state } : {}) })), conclusion: example[3] },
  pitfalls: [{ title: pitfall[0], text: pitfall[1] }], transfer,
  ...(flowchart ? { flowchart } : {})
});
const flow = (title, intro, nodes, edges, caption) => ({ title, intro, nodes: nodes.map(([id, label, detail, kind = 'process']) => ({ id, label, detail, kind })), edges: edges.map(([from, to, label]) => ({ from, to, ...(label ? { label } : {}) })), caption });

export const assemblyDepth = { ...assemblyStackDepth, ...assemblyDebugDepth };

assemblyDepth['assembly-first-instructions'] = {
  'a-machine-you-can-question': dive('Follow the artifact through three boundaries', [
    'A useful debugging record separates what you intended, what you built, and what you ran. The editor is an intention expressed as text. Assembly produces a concrete byte sequence. Booting makes that sequence part of a machine whose state can change. Each boundary can succeed independently of the next: valid bytes can implement the wrong message, and correct source can coexist with an older running image.',
    'Give each experiment a prediction before running it. For a two-character program, the prediction should name the complete visible sequence, including repeated characters. This makes a mismatch useful evidence. An unexpected first character points to a different boundary than a failed assembly, because the former already establishes that some program reached an output operation.'
  ], ['One edit, two possible artifacts', 'Suppose a working routine prints LM. Change only the first character to N and track what becomes different.', [
    ['Edit the intention', 'The text now requests NM, but the existing image still contains the immediate that requested L. Saving text does not rewrite memory in an already running guest.', 'editor: NM; last image: LM'],
    ['Build a new image', 'Successful assembly translates the changed operand. Record the build result before reasoning about CPU behavior; a syntax error would leave the desired new artifact unavailable.', 'new image requests NM'],
    ['Run and compare', 'Boot the new image and compare NM with the prediction. If LM remains visible, first establish which image actually ran. Use that artifact to explain the observation before making the next edit.', 'expected visible sequence: NM']
  ], 'The evidence chain connects a particular edit to particular bytes and finally to an observed effect.'], ['Treating a save as execution', 'A changed editor buffer establishes that the text was edited. A successful build and a run of that artifact connect the edit to CPU execution.'], 'If changing a comment leaves the output identical, what did that test establish? Only that this observation is compatible with comments not affecting instruction bytes; inspect a fresh build to connect the explanation to the artifact.', flow('From an edit to evidence', 'Follow the successful path, then use the failure branch to locate the next useful action.', [['edit','Edit source','State the intended character sequence.'],['build','Assemble image','Translate the current source snapshot.'],['valid','Build successful?','A failed build cannot supply the intended new image.','decision'],['repair','Inspect assembler error','Repair source notation before evaluating runtime meaning.'],['run','Boot the new image','The CPU receives a particular byte sequence.'],['observe','Compare with prediction','Use the first mismatch to choose the next experiment.','terminal']], [['edit','build'],['build','valid'],['valid','repair','No'],['repair','edit'],['valid','run','Yes'],['run','observe']], 'Successful assembly answers whether the source can become bytes. Observation answers what those bytes did.')),
  'state-before-syntax': dive('Track unknowns as carefully as known values', [
    'A trace is a small model, so choose its columns according to the question. To explain one character, AL and the output sequence may suffice. To explain a return, stack state matters too. You do not need every register in every trace, but leaving a column out means you cannot draw conclusions about it from that trace.',
    'Use a question mark for a value you have not established. Unknown means the current explanation provides no basis for choosing a value. Keep that uncertainty visible until setup or an instruction supplies the missing information. An instruction can turn one unknown into a known value without resolving any other unknowns. This is the beginning of reasoning about program preconditions.'
  ], ['Separate preparation from observation', 'Assume only that the display is blank. Trace two writes followed by one output request.', [
    ['Establish AL', 'MOV AL, 80 gives a definite byte value regardless of the previous AL. It does not establish AH or produce visible output.', 'AL=80; AH=?; output=""'],
    ['Replace AL', 'MOV AL, 81 overwrites the only prepared character. There is no queue of prior register assignments waiting for the display.', 'AL=81; AH=?; output=""'],
    ['Request output', 'CALL putc reads the current AL, so the visible character is Q. The helper preserves its documented register state, but that promise does not retroactively print P.', 'AL=81; output="Q"']
  ], 'The trace explains both the observed Q and the absent P using changes to separate pieces of state.'], ['Inventing initialization', 'Writing zero into an unmentioned trace column can hide a dependency on stale state. Mark it unknown until setup or an instruction defines it.'], 'Can you infer AX from the final AL alone? No. AX includes AH, whose value this trace never established. A wider observation needs a wider precondition.'),
  'source-and-machine-code': dive('Derive addresses from encoded instruction lengths', [
    'An instruction encoding is a byte-level agreement between the assembler and the processor. One byte may identify an operation while later bytes describe registers, constants, or displacements. Their roles depend on the opcode and decoding environment. A byte that represents an immediate in one position can represent an opcode at a different starting position.',
    'This is why a byte listing needs an address column and instruction boundaries. Searching the image for a familiar character code is not enough to identify the instruction that prints it. That same byte might occur in data, a constant, padding, or another instruction. Connect a source line to its emitted location before interpreting the surrounding bytes.'
  ], ['Locate two immediate moves', 'Consider consecutive MOV AL, 0x52 and MOV AL, 0x53 beginning at offset 0x0120 in a correctly decoded excerpt.', [
    ['Encode the first operation', 'The first instruction occupies B0 52. B0 selects the immediate-to-AL form, and 52 supplies its byte value.', '0x0120: B0 52'],
    ['Advance by encoded length', 'The next instruction starts two bytes later, at 0x0122. An intervening comment or label would not reserve another instruction-sized slot.', '0x0122: B0 53'],
    ['Distinguish reading from running', 'A byte viewer can show both constants even though executing these moves alone prints nothing. Execution leaves AL containing 0x53 after the second write.', 'next offset=0x0124; AL=0x53']
  ], 'The listing explains storage and boundaries. A separate execution trace explains the final register value.'], ['Interpreting every matching byte as data', 'Finding 0x53 in the file does not prove it is the intended character constant. Its instruction context determines its role.'], 'Would inserting an empty comment line move the second instruction? No. Would inserting another MOV AL, immediate move it? Yes, that form adds two encoded bytes in this environment.'),
  'fetch-decode-execute': dive('Follow the next address as an output of execution', [
    'Besides ordinary data, each executed instruction determines where execution continues. For a sequential instruction, the next address follows its complete encoding. A control-transfer instruction replaces that continuation with a destination. Thinking of the instruction pointer as another output prevents the misleading idea that source text scrolls past the CPU one line at a time.',
    'The architectural trace describes effects that a correct implementation must provide. It intentionally leaves out overlapping internal work, caches, and prediction. Those details matter for performance, but they are not needed to prove which character a simple straight-line program prepares. Keep correctness questions and timing questions separate, and state the evidence needed to answer each.'
  ], ['Trace positions with different instruction lengths', 'Use a hypothetical listing whose instruction boundaries are already known: operations begin at 0x0200, 0x0202, and 0x0205.', [
    ['Execute the first operation', 'A two-byte register move at 0x0200 leaves the next sequential position at 0x0202. Its data effect and its address effect are distinct trace entries.', 'IP: 0x0200 -> 0x0202'],
    ['Execute a transfer', 'Suppose the three-byte instruction at 0x0202 jumps to 0x0220. The next fetch uses destination 0x0220, skipping the sequential position 0x0205.', 'IP: 0x0202 -> 0x0220'],
    ['Identify skipped work', 'Bytes at 0x0205 remain present in the image but are not executed on this path. Their existence cannot establish that their effects occurred.', 'executed addresses: 0200, 0202, 0220']
  ], 'A path through addresses is stronger evidence than a count of visible source lines.'], ['Counting trace rows as clock cycles', 'A two-byte instruction is not necessarily faster than a three-byte instruction, and one architectural row need not consume one clock.'], 'If a skipped instruction would have prepared a different character, should it appear in the value trace? No. Only instructions on the executed path change the traced architectural state.'),
  'read-a-source-line': dive('Classify each line before giving it runtime meaning', [
    'Source notation mixes several kinds of instruction to different readers. A mnemonic such as MOV describes a CPU operation. A label gives NASM a name for a position. A directive controls assembly. A comment speaks only to the human reader. Separating these roles keeps an explanation from assigning runtime work to text that never becomes an executed instruction.',
    'Then classify the operands of a real instruction. A register names storage. An immediate supplies a value in the encoding. Later, a bracketed operand will request memory access. Operand order answers which part changes, but operand kind answers what the source value actually means. Read both before writing a trace row.'
  ], ['Read a compact routine aloud', 'Take ready: MOV BL, 0x54 followed by MOV AL, BL and CALL putc. The label can share a source line with MOV.', [
    ['Identify the named position', 'ready names where the first MOV begins. Reaching the label does not itself copy a value or create a separate machine step.', 'label ready -> first instruction'],
    ['Interpret both copies', 'The first MOV supplies an immediate byte to BL. The second copies the current contents of BL into AL, retaining BL as an independent copy.', 'BL=0x54; AL=0x54'],
    ['Interpret the request', 'CALL putc is an actual control transfer to a supplied routine. Its input agreement makes AL meaningful as a character code, so this path prints T.', 'output="T"']
  ], 'Reading the line structure first gives each later state change a precise cause.'], ['Treating spelling as a guaranteed error check', 'Some misspelled instruction-like tokens can be accepted as labels. Explicit label colons and assembler warnings help reveal unintended source structure.'], 'If you rename ready consistently wherever it is referenced, should the output change? No. The spelling names a position for the assembler; the CPU follows the resulting addresses.'),
  'mov-means-copy': dive('Preserve an old value before overwriting its last copy', [
    'A sequence of copies can destroy information even though no instruction performs arithmetic. The important question is whether the old destination value still has a future use. If it does, preserve it somewhere that the upcoming writes will not also overwrite. That location becomes a temporary, meaning storage used to bridge a short interval in the calculation.',
    'Each MOV samples its source once and leaves an independent copy in the destination. Later writes affect whichever storage the new instruction selects. This local rule is enough to derive a correct exchange, and it scales to preserving an address while reusing a register for output.'
  ], ['Exchange two byte values', 'Begin with AL=14 and BL=29, and assume CL is available as temporary storage.', [
    ['Save the value at risk', 'MOV CL, AL preserves 14 before AL is overwritten. The original BL value remains available in BL.', 'AL=14; BL=29; CL=14'],
    ['Install the second value', 'MOV AL, BL changes AL to 29. It does not consume BL, and the saved original AL remains in CL.', 'AL=29; BL=29; CL=14'],
    ['Complete the exchange', 'MOV BL, CL restores the saved 14 into BL. Both original values survive in their requested final destinations.', 'AL=29; BL=14; CL=14']
  ], 'Three copies work because the first preserves information that the second would otherwise destroy.'], ['Saving too late', 'MOV AL, BL followed by MOV CL, AL saves the replacement value 29. Preserving the old 14 requires making the copy before AL is overwritten.'], 'Could CH replace CL as the temporary here? Yes, if its existing value is disposable and no other operation overwrites it before the final copy. Temporary selection depends on future uses.'),
  'why-printing-is-explicit': dive('A helper reads arguments at the time of the call', [
    'An interface is a contract about a boundary between independently understandable pieces of code. For putc, the input is the byte in AL at entry. The visible effect is one character request. The preservation promise tells you which caller state remains valid afterward. These are three separate parts of the contract, and all three matter when composing operations.',
    'Preparing an argument is itself a state change. Although putc preserves general registers, loading its argument into AL may already have destroyed a low byte you intended to keep. Preservation describes what the helper does from its entry state; it cannot protect the caller from writes made before entry.'
  ], ['Print without losing a needed byte', 'Suppose AL contains a useful numeric byte 9, but the next visible marker must be U before that numeric value is used again.', [
    ['Save the live input', 'MOV BL, AL keeps the numeric 9 available. This must happen before preparing the marker, because AL is the helper’s argument register.', 'AL=9; BL=9'],
    ['Prepare and request', "MOV AL, 'U' replaces AL with 85. CALL putc displays U and preserves that entry value of AL under the course contract.", 'AL=85; BL=9; output="U"'],
    ['Recover the earlier value', 'MOV AL, BL restores 9 for the later calculation. The preservation promise made BL a suitable home across this particular call.', 'AL=9; BL=9']
  ], 'The caller protects values while preparing arguments; the callee protects the state its contract promises.'], ['Expecting a helper to remember earlier assignments', 'Two calls with no intervening AL change receive the same input. putc does not maintain a queue of the values previously loaded into AL.'], 'Would loading U into BL and calling putc print U? Only if AL independently already held U. The documented argument register determines what the helper reads.'),
  'the-scaffold-contract': dive('Treat setup as a list of established preconditions', [
    'A precondition is a fact a routine relies on before its first instruction. The harness establishes usable segments, a stack, output helpers, and a return path. These facts let a small lesson omit setup while remaining executable. They do not become universal properties of assembly language simply because every early exercise shares them.',
    'A postcondition describes what must be true when the routine finishes. Here, the wrapper must recover its saved continuation and reach its halt path. The routine must preserve the stack state and continuation needed by that return path. A routine that prints correctly but corrupts its return information has fulfilled the visible part of the task while violating the surrounding execution agreement.'
  ], ['Account for lesson entry and exit', 'The wrapper initializes SP to 0x7c00, then makes the ordinary near call into the lesson.', [
    ['Reserve the continuation', 'The call places a two-byte return offset on the stack, so the lesson begins at SP=0x7bfe. Those bytes belong to the active call.', 'entry SP=0x7bfe'],
    ['Use the promised services', 'A short body can prepare a character and call putc. The supplied helper manages its own temporary stack use and returns with its entry stack position restored.', 'after helper return: SP=0x7bfe'],
    ['Return to the wrapper', 'The normal lesson return consumes the saved offset and restores SP to 0x7c00. The wrapper can then stop deliberately with the display intact.', 'after lesson return: SP=0x7c00']
  ], 'A correct tiny routine has both a visible result and a valid continuation back into its environment.'], ['Assuming arbitrary entry registers are zero', 'The harness documents specific initial conditions. Values outside that promise should be initialized explicitly when your code needs them.'], 'Why should a lesson avoid placing scratch data over its saved return word? Because the same bytes later determine where execution continues; writable memory can still contain live control information.'),
  'build-your-first-program': dive('Choose the first differing trace row', [
    'When a program produces the wrong sequence, compare predictions and observations at the earliest meaningful boundary. The final screen can contain several downstream effects of one early mistake. Fixing the first divergence is more informative than changing every suspicious line, because later behavior may become correct once its input is repaired.',
    'For output routines, the useful boundary is each call. Record the AL value immediately before the call and the new character immediately afterward. This creates a one-to-one explanation between prepared arguments and visible effects. It also separates two distinct errors: preparing the wrong value and making the correct request at the wrong time.'
  ], ['Diagnose repeated output', 'A routine should print VW but prints WW after loading both characters before either output call.', [
    ['Predict the overwritten value', "MOV AL, 'V' initially prepares the correct first argument. MOV AL, 'W' then replaces it before anything consumes V.", 'after two writes: AL=87'],
    ['Explain the first mismatch', 'The first putc call reads W. The earliest divergence is already at the first call, so investigating newline cannot explain this particular error.', 'first observed character: W'],
    ['Repair the ordering', 'Move the first output request between the two preparations. The calls now consume V and W at different moments, matching the intended trace.', 'prepare V -> print -> prepare W -> print']
  ], 'A useful repair changes the cause identified by the trace and makes a specific prediction about the next run.'], ['Changing constants when ordering is wrong', 'Replacing one literal may merely change which character repeats. The destroyed value must be consumed before its replacement arrives.'], 'What evidence would distinguish a missing second call from a repeated argument? One visible character suggests the missing request; two identical characters suggest two requests with the same input, though tracing confirms the cause.'),
  'evidence-and-transfer': dive('Make a second example test your explanation', [
    'An explanation becomes useful when it predicts a change you have not yet run. If you can identify which instruction supplied each output character, you can predict a reordered message or a repeated character without trial and error. This is transfer: applying the same mechanism under different input choices.',
    'Keep the strength of the conclusion proportional to the experiment. One successful message establishes one executed behavior in this harness. It does not establish how raw firmware initializes every register, whether the routine works with another calling convention, or how long it takes. The next chapters broaden the model by making those previously hidden assumptions explicit.'
  ], ['Compare two edits that look similar', 'Start from an understood XY routine with one preparation immediately before each putc call.', [
    ['Change a literal', "Replace 'X' with 'Z' while leaving every call in place. The first request receives a different byte; the second still receives Y.", 'predicted output: ZY'],
    ['Move a preparation', 'For the second experiment, restore X, then move the preparation of Y above the first call. Both requests now see Y because no later instruction restores X.', 'predicted output: YY'],
    ['Explain the difference', 'Both edits touched character-related source, but only the second changed which assignment reaches a particular call. The trace identifies that data-flow difference precisely.', 'same helper; different input histories']
  ], 'Predicting both outcomes shows how argument timing determines the message that each output request contributes.'], ['Treating a passing display as a complete specification', 'The display cannot show preserved registers or stack balance. Other requirements need their own observations and reasoning.'], 'If the same literal is written as its decimal code, should this change the first character? No. The assembler produces the same byte value, and the helper receives the same input pattern.')
};

assemblyDepth['assembly-numbers'] = {
  'bits-have-positions': dive('Build and verify a pattern by weights', [
    'Position and contents are different quantities. Bit 5 names a position whose unsigned weight is 32. Its contents can be zero or one; only a one contributes that weight to the total. This distinction matters when a later instruction asks you to set a numbered bit: the bit’s weight determines its numerical contribution.',
    'Conversion is easiest to check by reversing it. After choosing bits for a number, add their weights again. If the reconstructed value differs, either a position was skipped or a weight was confused with its index. Writing all eight positions also makes the capacity limit visible.'
  ], ['Construct the byte for 73', 'Work from the largest byte weight downward, retaining a remainder after each decision.', [
    ['Choose the largest fitting weight', '128 does not fit, but 64 does. Set bit 6 and subtract its weight from 73, leaving 9 for the lower positions.', '73=64+9'],
    ['Complete the smaller positions', '32 and 16 do not fit. Choose 8 and then 1. The remaining weights contribute zero, producing three set bits.', '01001001 = 64+8+1'],
    ['Check the direction back', 'Sum the chosen weights to recover 73. A mistaken choice of bit 5 contributes 32 and changes the reconstructed total immediately.', '0x49 = 73']
  ], 'Choosing weights and reconstructing their sum gives a checkable explanation of the pattern.'], ['Confusing index with weight', 'Setting bit 3 adds a contribution of 8 when it was previously clear. It does not mean adding 3.'], 'What changes if bit 0 of this byte is cleared? The value becomes 72 because the removed contribution is one; all other positions retain their values.'),
  'hex-as-grouped-binary': dive('Keep nibble boundaries visible', [
    'A nibble is a four-bit group. Hexadecimal is useful because each digit maps directly to one nibble without carrying information across digit boundaries. Two hexadecimal digits show a byte, and four show a word. This lets a programmer inspect high and low fields without converting the whole value into decimal first.',
    'Leading zeros are bookkeeping. Writing 0x003A communicates that you are examining a word while preserving the value also written as 0x3A. The actual instruction operand determines the stored width; leading zeros help the reader keep that width in mind.'
  ], ['Convert a word in independent pieces', 'Take 0x9B24 and translate each hexadecimal digit into four positions.', [
    ['Expand each digit', 'Nine is 1001, B is 1011, two is 0010, and four is 0100. Keep all four positions per group so boundaries stay aligned.', '1001 1011 0010 0100'],
    ['Identify the bytes', 'The high byte is 0x9B and the low byte is 0x24. This describes numerical significance in the word, before choosing any memory layout.', 'high=0x9B; low=0x24'],
    ['Check a selected bit', 'The final nibble 0100 has bit 2 set. Reading that nibble directly is quicker and less error-prone than converting the whole word to decimal.', 'bit 2=1; bit 0=0']
  ], 'Hexadecimal preserves visible groups of bits, which makes masks and instruction bytes easier to reason about.'], ['Dropping a leading bit within a group', 'Writing B as 1011 is fine, but writing 2 as 10 and concatenating without padding destroys the four-bit boundaries.'], 'What happens to the low byte if only the first hex digit changes to A? Nothing: the low byte remains 0x24 because the edit changes only the highest nibble.'),
  'one-value-many-spellings': dive('Separate input radix from output format', [
    'Radix means the base used to interpret digits. The assembler applies the source radix before producing machine bytes. The output helper later applies its own formatting rule. These two choices are independent, with the stored bit pattern between them. No tag in AX remembers which spelling you used in the editor.',
    'A reliable prediction therefore has three stages: parse the literal into an integer, fit that integer to the destination width, and apply the helper format. When the display surprises you, locate the first stage where your expectation differs. Changing the printer cannot repair a wrongly parsed source value.'
  ], ['Three inputs, one display', 'Compare MOV AX, 90, MOV AX, 0x5A, and MOV AX, 0b01011010 in separate runs.', [
    ['Interpret decimal', 'The unprefixed decimal literal 90 supplies ninety. A sixteen-bit register contains the pattern 0x005A for that value.', '90 decimal -> AX=0x005A'],
    ['Interpret hexadecimal and binary', 'Five times sixteen plus ten equals ninety; binary 64+16+8+2 also equals ninety. Both spellings therefore produce the same AX bits.', '0x5A = 0b01011010 = 90'],
    ['Apply the display contract', 'print_hex16 reads the same sixteen bits in every run and produces four hexadecimal digits. It cannot distinguish the earlier spellings.', 'all three display 005A']
  ], 'Different source text can express identical machine input, while one machine value can support many display formats.'], ['Reading 90 as hexadecimal accidentally', 'A visible output of 005A after loading decimal 90 is expected. Writing 0x90 would request a different value, decimal 144.'], 'If the requirement is decimal twelve but the display should use hex, what should AX contain? The value twelve, pattern 0x000C; the helper then prints 000C.'),
  'width-is-a-capacity': dive('Choose width from the largest required state', [
    'Capacity must cover both the input range and every intermediate state the calculation needs. A counter that labels 256 positions with values zero through 255 fits in a byte. A count that must report all 256 positions requires the value 256 and therefore does not. The difference comes from what the variable represents, even though the underlying collection is the same.',
    'Use a range statement before choosing a register. For unsigned n-bit storage, there are 2 to the power n patterns and the largest value is one less. Signed interpretation allocates some patterns to negative values, so derive its range separately before selecting a register width.'
  ], ['Choose a representation for a filled buffer', 'A buffer has 256 byte slots. Compare the position of its last slot with the number of occupied slots when full.', [
    ['Represent an index', 'With zero-based numbering, the last slot has index 255. Every valid index fits in an unsigned byte.', 'valid indices: 0 through 255'],
    ['Represent the full count', 'The number of occupied slots can be 256. A byte would retain zero for that pattern, making full and empty indistinguishable without extra state.', 'full count=0x0100'],
    ['Choose a wider count', 'A word holds both zero and 256 directly. The wider representation preserves the distinction needed by a bounds check or completion test.', 'AX can represent 0 through 256']
  ], 'Index range and count range answer different questions and can require different widths.'], ['Choosing width from a typical example', 'A test with ten slots does not establish that a byte counter works for the maximum permitted input. Derive the maximum first.'], 'Would a byte count work if the capacity were 255? Yes, an unsigned byte can represent every count from zero through 255, provided no intermediate calculation needs a larger value.'),
  'modular-numbers': dive('Keep the full answer beside the retained answer', [
    'Modulo arithmetic identifies values that differ by an exact multiple of the storage capacity. An unsigned byte retains the remainder after dividing by 256. Compare those retained bits with the application’s required result to decide whether wraparound is acceptable. An intentional ring counter and an exact inventory count may need different responses to the same wraparound.',
    'For subtraction, choose the representative between zero and 255 by adding enough multiples of 256. The retained pattern and the unlimited mathematical answer belong in separate trace columns; the latter remains negative. Keeping both numbers in the trace prevents a later unsigned comparison from silently answering the wrong question.'
  ], ['Trace both sides of zero', 'Use byte-sized operations and compare a sum past the upper boundary with a subtraction below zero.', [
    ['Add beyond capacity', '238+25 equals 263 mathematically. Removing one full group of 256 leaves the stored byte 7.', '263 = 1*256 + 7'],
    ['Subtract below zero', '4-9 equals -5 mathematically. Adding 256 selects the byte pattern 251, hexadecimal FB.', '-5 + 256 = 251 = 0xFB'],
    ['Reverse the subtraction', 'Adding 9 to the retained 251 gives 260, whose low byte is 4. The modular operation recovers the starting pattern even though the intermediate unsigned reading was large.', '(251+9) mod 256 = 4']
  ], 'The finite-width rules are consistent, but an exact quantity may require additional bits or an explicit overflow decision.'], ['Calling every wraparound a CPU error', 'The processor follows the defined width. The program must decide whether discarding the extra information is acceptable for its problem.'], 'If a byte timer wraps from 255 to zero, has time stopped? No. The representation repeated; interpreting elapsed time requires an explicit rule about wrapping and the maximum interval.'),
  'signedness-is-an-interpretation': dive('Assign meaning before choosing an ordering operation', [
    'A byte can encode a small unsigned count, a signed displacement, or a character code. The bit pattern itself does not force one meaning. Instructions that merely copy bits need no signedness choice, while comparisons and widening do. A program must carry that meaning in its data contract and instruction selection.',
    'For a signed byte whose top bit is set, subtract 256 from its unsigned reading to recover the signed value. This is equivalent to assigning the highest position weight -128. It also explains why two identical patterns remain equal while their position relative to another pattern can change with interpretation.'
  ], ['Compare the same two bytes twice', 'Take the patterns 0xD8 and 0x18, and write both interpretations before considering their order.', [
    ['Read them unsigned', 'D8 is 216 and 18 is 24. As nonnegative quantities, the first is larger than the second.', '216 > 24'],
    ['Read them signed', 'The first has its top bit set, so 216-256 gives -40. The second remains positive 24. Their order is now reversed.', '-40 < 24'],
    ['Keep copying separate', 'Moving either pattern between byte registers preserves it exactly. No conversion occurs merely because the surrounding explanation changes from count to displacement.', 'D8 stays D8']
  ], 'Signedness determines how comparisons and conversions interpret the stored bits.'], ['Treating the sign bit as a separate minus symbol', 'Clearing the top bit of D8 gives hexadecimal 58, or decimal 88. The positive magnitude 40 requires hexadecimal 28. Two’s complement assigns weights to all positions, including the negative weight of the top bit.'], 'Which interpretation should a byte length field use if negative lengths are impossible and values up to 200 are valid? Unsigned, because signed byte ordering would misread those larger valid lengths.'),
  'derive-negative-values': dive('Prove a negative encoding by cancellation', [
    'A two’s-complement negative pattern is chosen so that adding the corresponding positive magnitude leaves zero at the stated width. This gives a useful verification method: do the addition and discard only the carry beyond that width. If the retained result is not zero, the proposed negative representation is wrong.',
    'The width must stay fixed throughout the derivation. Inverting eight bits and inverting sixteen bits produce different strings of leading ones. Those extra ones are exactly what preserve a negative value when its representation is widened. They are not optional decoration in a machine register.'
  ], ['Derive negative thirteen at two widths', 'Begin from the positive magnitude thirteen, then choose the additive inverse separately for a byte and a word.', [
    ['Build the byte pattern', '256-13 equals 243, hexadecimal F3. The cancellation check gives 0x0D+0xF3=0x100, whose retained low byte is zero.', '8-bit -13 = 0xF3'],
    ['Build the word pattern', '65536-13 equals 65523, hexadecimal FFF3. This time the carry leaves bit 15, and the retained sixteen bits are zero.', '16-bit -13 = 0xFFF3'],
    ['Reject the wrong widening', '0x00F3 is positive 243 as a signed word. It retains the byte pattern but fails to preserve the intended numerical value -13.', '0x00F3 != signed -13']
  ], 'The cancellation check explains why the derived pattern is the additive inverse at the chosen width.'], ['Assuming every negative has a same-width positive opposite', 'The most negative signed value has no representable positive counterpart at that width. Negation therefore needs a range check at that boundary.'], 'How can you check a proposed word encoding of -21 quickly? Add 21 and confirm that the low sixteen bits are zero, while also checking that the pattern lies in the negative signed range.'),
  'widening-and-truncation': dive('Exact narrowing needs a range proof', [
    'Widening adds positions but still requires a meaning choice. Zero extension preserves an unsigned number; sign extension preserves a signed number. Narrowing removes positions and may merge several different source values into one pattern. Once the discarded bits are gone, the smaller destination cannot explain which source value existed.',
    'A round trip can expose information loss. Narrow a candidate, widen it using the intended signedness, and compare with the original value. If they differ, narrowing was not exact under that interpretation. This is a reasoning tool here; later implementations can use direct range comparisons to enforce the same requirement.'
  ], ['Test a narrowing candidate', 'Suppose a word value 0x01A6 is proposed for storage in one unsigned byte.', [
    ['Retain the low byte', 'The low eight bits are A6. The discarded high byte was 01, so the new pattern cannot encode the original unsigned 422.', '0x01A6 -> 0xA6'],
    ['Widen using the intended meaning', 'Zero extension gives 0x00A6, which is unsigned 166. Comparing with 0x01A6 reveals the lost contribution of 256.', '422-166=256'],
    ['Contrast signed widening', 'If A6 were a signed byte, sign extension would produce FFA6, representing -90. This conversion preserves the signed-byte meaning -90; the original word represented unsigned 422.', 'signed A6 -> FFA6 = -90']
  ], 'The destination pattern alone cannot recover discarded information or choose the interpretation for you.'], ['Checking only the low byte after a conversion', 'A matching low byte is guaranteed by truncation and therefore does not establish that the complete numerical value survived.'], 'Can unsigned 250 be narrowed to a byte exactly? Yes. Can signed 250? No, because signed byte range ends at 127 even though the raw pattern fits.'),
  'characters-are-encoded-data': dive('Count digits separately from numeric magnitude', [
    'A number stored in binary and a string of digit characters are different representations. The integer 58 fits in one byte, but the decimal text 58 uses two character codes. A terminator, if required by the string interface, consumes an additional byte. Derive storage requirements from the chosen representation, including every digit byte and required terminator.',
    'Formatting is a calculation that chooses digit values and maps each one to a character code. putc performs only the final character request. print_hex16 performs the earlier conversion too, using a fixed four-digit hexadecimal format. Knowing which work the interface promises explains why the helpers produce different displays from related input bits.'
  ], ['Represent the value fifty-eight', 'Compare a numeric byte, decimal text, and the hexadecimal helper output.', [
    ['Store the numeric value', 'Fifty-eight has byte pattern 0x3A. Sending this pattern directly to putc requests the character with that code, a colon.', 'numeric 58 -> 0x3A -> ":"'],
    ['Store decimal text', 'The character 5 uses 0x35 and 8 uses 0x38. A zero-terminated representation contains those two bytes followed by zero.', 'decimal string: 35 38 00'],
    ['Format the numeric word', 'With AX=58, print_hex16 emits 003A. Those four visible characters describe the same numeric value in a different radix.', 'hexadecimal display: 003A']
  ], 'Representation, conversion, and drawing a character are separate steps with separate storage requirements.'], ['Adding the character code for zero to every number', 'That shortcut converts a single digit from zero through nine. It does not convert a multi-digit quantity into a string.'], 'Why does numeric seven sometimes need one output call and sometimes four? putc can print the prepared digit character 7; print_hex16 formats a whole word as 0007.'),
  'make-an-interpretation-ledger': dive('Use one ledger to locate the first wrong assumption', [
    'A good ledger records source spelling, storage width, stored pattern, numerical interpretation, and output format. These are related facts but not interchangeable ones. A negative-looking display is especially misleading when the printer simply emits hexadecimal digits without interpreting a signed value.',
    'Write the intended meaning first, then derive the required pattern. This prevents the printer from becoming the source of truth about your arithmetic. It also makes a review concrete: another learner can challenge the width or extension decision without disputing the unrelated fact that the display contains four characters.'
  ], ['Explain a widened negative sample', 'A byte sample contains 0xE7 and the data contract says it is a signed displacement.', [
    ['Interpret the source', 'Unsigned E7 is 231, but the signed contract gives 231-256=-25. That meaning determines what widening must preserve.', 'width=8; pattern=E7; value=-25'],
    ['Choose the wider pattern', 'Sign extension fills the new positions with ones, producing FFE7. Zero extension would preserve unsigned 231.', 'width=16; pattern=FFE7; value=-25'],
    ['Explain the display', 'print_hex16 emits FFE7 because it formats the word pattern. It does not print a minus sign, and that absence does not make the value unsigned.', 'display format=hex16; output=FFE7']
  ], 'Every stage has its own reason, so a disagreement can be located without guessing at new constants.'], ['Changing the stored value to make the display look decimal', 'Hexadecimal output is a formatting choice. Altering a correct machine value to mimic decimal digits corrupts the representation.'], 'If the source contract changes to an unsigned measurement, what changes in this ledger? The byte pattern stays E7, but its meaning becomes 231, widening becomes 00E7, and the printed word changes accordingly.', flow('Choose a widening policy', 'The interpretation decision belongs to the data contract, before the wider operation.', [['read','Read byte and contract','Record both its bits and intended meaning.'],['signed','Signed quantity?','The same pattern may represent different numbers.','decision'],['zero','Fill upper bits with zero','Preserve the unsigned byte value.'],['sign','Copy the source sign bit','Preserve the signed byte value.'],['use','Use the wider value','Arithmetic now reads fully defined bits.'],['format','Choose output format','Display policy is a separate decision.','terminal']], [['read','signed'],['signed','sign','Yes'],['signed','zero','No'],['zero','use'],['sign','use'],['use','format']], 'The conversion establishes the wider bit pattern, which the printer then formats.'))
};

assemblyDepth['assembly-registers'] = {
  'names-select-bits': dive('Draw overlapping names on one storage ruler', [
    'Use bit positions as the stable reference, because names overlap. EAX covers positions 31 through 0, AX covers 15 through 0, AH covers 15 through 8, and AL covers 7 through 0. A destination write replaces exactly the selected region in this environment. Other views then observe the changed shared storage.',
    'This is different from an ordinary MOV between independent registers. AL and AH occupy disjoint byte regions, but AL and AX overlap. Saving AX in AL cannot preserve the entire word, because the proposed destination is only part of the source. A preservation plan needs both enough width and independent storage.'
  ], ['Update a single byte inside EAX', 'Begin with EAX=0x8C2176D5 and replace AH with 0x4B.', [
    ['Separate the four bytes', 'Write the register as 8C, 21, 76, D5 from highest significance to lowest. AH names the third byte in this written order.', 'EAX: 8C | 21 | 76 | D5'],
    ['Apply the narrow write', 'MOV AH, 0x4B replaces only 76. AL retains D5 and the upper word retains 8C21.', 'EAX: 8C | 21 | 4B | D5'],
    ['Read every overlapping view', 'The complete value is now 8C214BD5. AX observes 4BD5, AH observes 4B, and AL observes D5; these are consistent views of one result.', 'AX=4BD5; AH=4B; AL=D5']
  ], 'The byte ruler makes both changed and preserved bits explicit without guessing from the immediate value.'], ['Counting register names as independent variables', 'Writing AX changes both AL and AH because they overlap. A trace that leaves their old values unchanged contradicts the storage layout.'], 'If AL is cleared next, what becomes of AX? It becomes 4B00 because AH still contains 4B.'),
  'trace-overlapping-writes': dive('Carry unchanged columns into every row', [
    'A partial-write trace should preserve the untouched columns visibly. Recomputing the whole word mentally after every line invites accidental clearing of high bytes. Treat each instruction as a precise replacement operation on the existing row, then copy the unchanged parts into the next row.',
    'This method also reveals dependencies on initialization. If the first instruction writes AL but a later printer reads AX, the trace should still show AH as unknown unless some earlier instruction defined it. An unknown high byte identifies the part of the printer argument that still needs initialization.'
  ], ['Compare two nearly identical sequences', 'Start with AX=0xC371, then execute MOV AL, 5, MOV AH, 0x26, and MOV AX, 9.', [
    ['Write the low byte', 'The destination AL selects eight positions, so the small constant 5 replaces only 71. The C3 high byte remains visible.', 'AX=C305'],
    ['Write the high byte', 'The second instruction replaces C3 with 26 while preserving the recently written 05. The complete word now combines values from two separate writes.', 'AX=2605'],
    ['Write the full word', 'The final destination AX covers both bytes. The constant 9 is represented as 0009, replacing the high byte as well as the low byte.', 'AX=0009']
  ], 'The size of the written numeral does not determine the size of the register update.'], ['Assuming a small immediate implies a narrow write', 'MOV AX, 9 writes sixteen bits, including eight high zeros. MOV AL, 9 writes only eight bits and can leave a nonzero AH.'], 'What would the last result be if the final instruction used AL? AX would be 2609. Only the destination name changed, but the preserved region changed with it.'),
  'eax-and-ax': dive('Describe the allowed write set before selecting an instruction', [
    'A write set is the collection of bits or locations an operation may change. When a requirement says replace the low word and keep the high word, translate that directly into positions 15 through 0 may change and positions 31 through 16 must survive. This identifies both the replacement region and the input bits that must survive.',
    'A narrow instruction implements that requirement naturally here. If a wider instruction is used, the program must explicitly reconstruct the preserved region from an earlier copy. The extra work is unnecessary when the architecture already offers a destination view matching the required write set.'
  ], ['Repair a destructive whole-register write', 'EAX initially contains 0x5E90A143. The low word should become 0x072B.', [
    ['Predict the broad write', 'MOV EAX, 0x072B creates the full 32-bit value 0000072B. The original 5E90 upper word is gone, although the low-word display looks correct.', 'wrong complete result: 0000072B'],
    ['Select the matching view', 'MOV AX, 0x072B writes only the low sixteen positions. The new complete result retains the initial high word.', 'correct complete result: 5E90072B'],
    ['Change the preserved input', 'Repeat the reasoning with initial EAX=0xB462A143. The same instruction should preserve B462, showing how the preserved region follows the actual input state.', 'second result: B462072B']
  ], 'Correctness includes preserved state, so observing only the replaced portion is insufficient.'], ['Hard-coding the expected high half', 'Reconstructing one known initial pattern can pass one demonstration while failing whenever the input changes. Preservation should follow the actual input state.'], 'Would MOV AL, 0x2B complete this task? No. It would leave the old AH value A1, producing the wrong low word A12B.'),
  'bitness-is-not-mode': dive('Keep three independent size questions separate', [
    'Operand size describes how many data bits an instruction processes. Address size describes how an effective address is formed and which address registers participate. Execution mode determines the broader architectural environment. Defaults and prefixes connect these properties; record all three when explaining an instruction.',
    'In the course, BITS 16 matches the real-mode decoding defaults while a 386-or-newer processor supplies wider registers. NASM can encode a particular 32-bit operand with a prefix. The prefix applies to that instruction’s operand size. The processor’s protection state and the following routine’s setup remain unchanged.'
  ], ['Use a wider value in the same environment', 'Compare MOV AX, 0x3142 with MOV EAX, 0x76543142 in a BITS 16 source region.', [
    ['Read the first destination', 'AX requests a sixteen-bit data result. The CPU remains in the established real-mode environment before and after the move.', 'operand width=16'],
    ['Read the second destination', 'EAX requests a thirty-two-bit data result. NASM supplies the encoding needed for that operand size under the sixteen-bit defaults.', 'operand width=32; mode unchanged'],
    ['Identify what did not follow', 'No GDT, protected-mode code segment, or paging structure was created by this move. Wider arithmetic is available without claiming those unrelated conditions.', 'EAX=76543142; still real mode']
  ], 'A register-width choice is local to the operation; an environment transition requires separate architectural setup.'], ['Adding BITS 32 just to use EAX', 'That changes NASM’s defaults for subsequent encodings. It does not make a real-mode CPU decode those bytes under matching new defaults.'], 'Can print_hex16 display all of the second result in one call? No. It reads AX, so its interface still shows only 3142 regardless of the previous instruction’s operand width.'),
  'register-families': dive('List implicit operands before assigning temporary registers', [
    'An explicit operand appears in the instruction text. An implicit operand is fixed by the instruction definition even when its name is absent. A routine’s register plan must include both. Otherwise a temporary may be overwritten by an instruction that never visibly mentions that register.',
    'General-purpose registers can serve many software roles. Each instruction form still specifies which registers can occupy its operand positions. A count, product, address, and return value may each have different legal or conventional homes. Learn each instruction’s complete read and write behavior before composing it with nearby code.'
  ], ['Notice the hidden second result of multiplication', 'In a word multiplication, suppose AX=400, BX=300, and DX currently holds an unrelated value that will be needed later.', [
    ['Identify the complete inputs', 'MUL BX reads AX and BX as unsigned words. The source text names BX, but AX is also an input selected by the instruction form.', '400*300=120000'],
    ['Identify the complete outputs', 'The product occupies DX:AX. Since 120000 is hexadecimal 0001D4C0, DX becomes 0001 and AX becomes D4C0.', 'DX:AX=0001:D4C0'],
    ['Preserve the unrelated value', 'If old DX remains live, save it in independent storage before MUL. Moving it afterward would save the new product half.', 'old DX must survive elsewhere']
  ], 'A register-safety check must include both explicit and implicit operands from the instruction’s full contract.'], ['Using DX as a permanent temporary near MUL or DIV', 'Those forms assign DX a defined arithmetic role. A temporary allocation must account for that implicit use.'], 'Why can a register named CX still hold a character code? Ordinary copies do not enforce the historical count role. The restriction appears only when an instruction implicitly uses CX as a count.'),
  'data-flow-and-liveness': dive('Preserve values across the interval that needs them', [
    'A value remains live until its final required use. A register can hold a live value now, become disposable after its final use, and later hold another live value. Identifying these intervals lets you choose the saves needed across each overwrite and reuse storage after its previous value expires.',
    'An observation can be a final use, but only if no later calculation needs the original. Before preparing another argument, ask whether its destination overlaps anything still live. A correct helper preservation contract protects its entry state; the caller still owns the argument preparation that precedes it.'
  ], ['Print two values without losing the first', 'AX contains 37 and BX contains 12. You want to print BX and then compute the original AX plus BX.', [
    ['Preserve the future addend', 'MOV CX, AX saves 37 before AX is reused as the printer argument. CX is suitable because the supplied printer preserves it.', 'CX=37; BX=12'],
    ['Prepare the observation', 'MOV AX, BX makes print_hex16 show 000C. This change is safe because the original AX value now has a live copy in CX.', 'AX=12; printed 000C'],
    ['Resume the calculation', 'MOV AX, CX restores 37, then ADD AX, BX produces 49. Once that addition consumes the saved value, its old copy may become disposable.', 'AX=49 = 0x0031']
  ], 'A preservation plan follows future uses and the exact interval in which a register is repurposed.'], ['Saving every value after the call', 'A save performed after argument preparation or an overwriting call preserves the replacement value; recovering the earlier live value requires a copy made before that overwrite.'], 'Could DX replace CX here? Yes under the supplied helper contract and this instruction sequence. If multiplication were inserted, you would need to reconsider DX’s implicit arithmetic role.'),
  'explicit-widening': dive('Make every destination bit part of the argument', [
    'A byte-to-word conversion must define the new high byte. Leaving AH unchanged does not implement either signed or unsigned widening; it combines a new input with unrelated old state. MOVZX and MOVSX make the policy explicit and remove that dependency from the calculation.',
    'Interpretation comes from the producer’s contract. A byte count normally wants its nonnegative magnitude preserved, while a signed adjustment may need negative values. Testing only a positive small byte cannot distinguish the policies because both produce zeros in the new high positions for those inputs.'
  ], ['Use an input that separates the policies', 'Take AL=0xB9 with arbitrary previous AH. Compare unsigned and signed conversion into a complete word.', [
    ['Derive the unsigned meaning', 'B9 is 185. MOVZX AX, AL creates 00B9, so every bit of AX is determined by the source byte and zero-fill rule.', 'unsigned result: AX=00B9'],
    ['Derive the signed meaning', 'As a signed byte, 185-256=-71. MOVSX AX, AL creates FFB9, the word representation of the same negative number.', 'signed result: AX=FFB9'],
    ['Test the incomplete alternative', 'A plain load into AL would leave AH unchanged. With AH=23, AX would become 23B9, which represents neither intended widened value.', 'stale-high-byte result: 23B9']
  ], 'An adversarial high-bit input reveals the representation choice that a friendly positive example would hide.'], ['Choosing the extension from the destination width alone', 'Both instructions produce a word. The source contract determines which numerical value must survive in the wider destination.'], 'What byte input makes both conversions agree? Any pattern from 00 through 7F, because its signed and unsigned readings are identical and its sign bit is clear.'),
  'observe-a-wide-register': dive('Design an observation that covers the required bits', [
    'An observation has a scope. print_hex16 covers sixteen bits, so it cannot prove preservation of all thirty-two bits in EAX. Two different complete states can produce the same visible low word. To distinguish them, deliberately move the unobserved portion into a position the interface can display.',
    'Preserve the original if it remains part of the experiment. A diagnostic shift changes data and arithmetic flags. Performing it on a copy protects the original register value, but not automatically every other live register or flag. The observation plan should state what it may overwrite.'
  ], ['Expose a hidden upper-half defect', 'Compare the candidate states EAX=0x927B006D and EAX=0x0000006D.', [
    ['Observe the low word', 'A direct print_hex16 call prints 006D in both cases. This observation cannot tell whether the upper word was preserved or accidentally cleared.', 'both low observations: 006D'],
    ['Preserve and shift', 'Save EAX in EDX, then use a working copy in EAX and shift it right sixteen positions. Its low word now contains the original upper word.', 'working AX=927B or 0000'],
    ['Print and restore', 'Print the shifted word, then restore EAX from EDX if needed. Label the display order so low-first output is not mistaken for a conventional high-first hexadecimal number.', 'upper observations differ']
  ], 'Observe both the replaced region and every region the requirement says to preserve.'], ['Destroying the evidence while inspecting it', 'Shifting the sole copy of EAX loses its original low word. Save it before the diagnostic operation if later steps still need the full value.'], 'Would printing AX twice improve coverage? No. Repeating the same narrow observation adds no information about the upper sixteen bits.'),
  'long-mode-caveat': dive('Attach a rule to the environment where it applies', [
    'Apply each architecture rule within its stated execution environment. In 64-bit mode, a write to a 32-bit general-purpose destination also determines the upper half of its associated 64-bit register by clearing it. That specified rule applies to 32-bit general-purpose destinations in 64-bit mode. Byte and word destinations preserve their surrounding register bits.',
    'Keep this preview separate from the executable real-mode exercises. RAX is not a register name for the current lesson environment. The useful lesson is methodological: state the mode, destination width, and affected larger view before borrowing an example from another x86 context.'
  ], ['Contrast three writes in a 64-bit thought experiment', 'For each independent case, begin with RAX=0xA1B2C3D4E5F60718.', [
    ['Write AL', 'MOV AL, 0x29 replaces only the lowest byte. Every higher position retains its initial value.', 'RAX=A1B2C3D4E5F60729'],
    ['Write AX', 'MOV AX, 0x29 replaces the low word with 0029 but preserves the higher forty-eight bits.', 'RAX=A1B2C3D4E5F60029'],
    ['Write EAX', 'MOV EAX, 0x29 produces a 32-bit result and, in this mode, clears the upper thirty-two bits of RAX.', 'RAX=0000000000000029']
  ], 'The destination names are related, but their architectural effects must still be stated individually.'], ['Importing a 64-bit example into real mode unchanged', 'Assembler acceptance, available register names, and decoding assumptions depend on the target environment. Keep this preview as a paper trace while the checkpoint retains its real-mode environment.'], 'Does this special EAX rule imply that writing AX clears the upper word of EAX? No. The sixteen-bit write preserves surrounding bits in the contexts discussed here; the special rule concerns a 32-bit destination in 64-bit mode.'),
  'repair-and-generalize': dive('Test preservation with deliberately different neighboring bits', [
    'A preservation requirement is relational: the output’s untouched region must equal the input’s corresponding region. The preserved region must therefore follow the incoming value across every invocation. This distinction suggests a direct testing strategy: vary the region that should survive while holding the requested replacement constant.',
    'Use visually distinct byte patterns so an accidental shift, reversal, or clearing is easy to notice. Then derive the full output before choosing a printer arrangement. The observation should cover both the modified portion and the preserved portion, because either can be wrong independently.'
  ], ['Review a low-byte replacement', 'The goal is to replace AL with 0x35 while preserving every other bit of EAX.', [
    ['Predict one complete result', 'From EAX=0x7192ABC4, the correct result is 7192AB35. Only the final byte changes.', 'input 7192ABC4 -> 7192AB35'],
    ['Challenge the preserved region', 'From EAX=0xD863EFC4, the same operation must produce D863EF35. Hard-coding the first high bytes would now fail.', 'input D863EFC4 -> D863EF35'],
    ['Check an overly broad repair', 'MOV AX, 0x35 would clear AH in both cases. Observing only AL would miss this defect, while a word or full-register trace exposes it.', 'wrong first result: 71920035']
  ], 'Changing the preserved region’s initial value makes its relationship to the output directly observable.'], ['Testing only an initially zero neighbor', 'An unwanted clear is invisible when the neighboring bits already contain zero. Choose nonzero neighbors to expose that mistake.'], 'What additional case checks that old AL is irrelevant? Keep the higher bytes fixed but vary the starting low byte; all results should still end in 35.', flow('Select and verify a register write', 'Choose the destination from the required bit region, then test both replacement and preservation.', [['require','Mark allowed changes','Identify exactly which bits may change.'],['fit','Does one view match?','AL, AH, AX, and EAX select different regions.','decision'],['narrow','Use the matching view','Write only the requested region.'],['preserve','Preserve neighboring bits','Use an explicit copy or mask when a wider operation is necessary.'],['predict','Derive the full result','Keep untouched input bits visible.'],['verify','Observe every required region','Vary the preserved input to expose hard-coded repairs.','terminal']], [['require','fit'],['fit','narrow','Yes'],['fit','preserve','No'],['narrow','predict'],['preserve','predict'],['predict','verify']], 'A correct low-word display alone cannot establish that the high word survived.'))
};

assemblyDepth['assembly-arithmetic'] = {
  'two-results-of-arithmetic': dive('Treat flags as part of the instruction result', [
    'A numerical destination and its flags are parallel outputs of one operation. The retained bits say what fits in the destination. Flags describe selected properties of the operation at that width. Neither is a complete substitute for the other: a zero byte could result from adding zero to zero or from wrapping a larger sum.',
    'Write a trace with the full mathematical answer first. Then reduce to the operand width and derive each flag according to its own definition. This order prevents the common circular mistake of assuming a flag because the displayed hexadecimal result looks large or negative.'
  ], ['One result, two interpretations', 'Add byte operands 0x70 and 0x30, interpreting the same calculation both unsigned and signed.', [
    ['Compute without truncation', 'The unsigned values are 112 and 48, giving 160. Both signed inputs are also positive, so their signed mathematical sum is likewise 160.', '112+48=160'],
    ['Retain the byte', '160 fits in eight unsigned bits and has pattern A0. Interpreted as a signed byte, A0 means -96.', 'retained byte=A0'],
    ['State independent flags', 'No unsigned carry was needed, so CF=0. The signed result exceeds 127, so OF=1. The retained pattern is nonzero and has its top bit set.', 'CF=0; OF=1; ZF=0; SF=1']
  ], 'All four flags are consistent once each is tied to its own precise question.'], ['Using overflow as a synonym for carry', 'An operation can set one, both, or neither. The correct flag depends on the interpretation and requirement.'], 'Would widening the inputs to words before adding preserve positive 160? Yes. The word signed range contains 160, so the wider arithmetic can represent that intended sum without signed overflow.'),
  'unsigned-carry': dive('Recover the full unsigned sum from result and carry', [
    'For one byte addition, the largest full sum of two byte operands is 510. A nine-bit result therefore suffices. The destination retains the lower eight bits and CF records the extra bit. Together they describe the full unsigned sum as result plus CF times 256.',
    'That relationship explains why a carry can feed a wider addition. The extra bit represents one unit of the next higher byte position, with weight 256 relative to the low byte. Moving from byte pieces to word pieces changes the positional weight to 65536 but keeps the same reasoning.'
  ], ['Reconstruct a sum that wrapped', 'Add 221 and 58 using an eight-bit destination.', [
    ['Compute the full quantity', 'The mathematical sum is 279, which exceeds the largest unsigned byte value 255 by 24.', '221+58=279'],
    ['Separate high and low pieces', '279 equals 256 plus 23. The byte retains 23, hexadecimal 17, and the extra group of 256 sets carry.', 'result=0x17; CF=1'],
    ['Verify the reconstruction', 'Combining the retained result and carry gives 23+1*256=279. Ignoring CF would report 23 and lose an entire positional unit.', '23+256=279']
  ], 'Carry provides the extra positional unit that the next higher arithmetic piece must include.'], ['Adding carry back into the same low byte', 'The carried unit belongs at the next higher position. Adding one to the low byte produces 24; reconstructing 279 requires adding the carry’s positional weight of 256.'], 'What full unsigned sum corresponds to result 0x08 with CF=1? It is 264 for a byte addition. For a word addition, the same low result and carry would represent 65544.'),
  'unsigned-borrow': dive('Interpret carry after subtraction as a borrow request', [
    'On x86, CF after SUB answers whether the unsigned first operand was too small to subtract the second without borrowing. The retained bits still follow modular arithmetic. A large hexadecimal result after a small-minus-large subtraction therefore does not imply that the mathematical answer was a large positive quantity.',
    'The borrow represents one unit from the next higher position. That position can supply it if the full number has enough magnitude. Consequently a low-word borrow does not by itself establish that an entire multiword subtraction underflowed. Only the final borrow out of the highest piece answers that larger question.'
  ], ['Follow a low-byte borrow numerically', 'Compute 18-47 in an eight-bit destination.', [
    ['Compare the unsigned inputs', 'Eighteen is smaller than forty-seven, so the subtraction needs a borrow. CF becomes one.', '18 < 47; CF=1'],
    ['Derive the retained pattern', 'The unlimited result is -29. Adding 256 selects the equivalent byte pattern 227, hexadecimal E3.', '18-47=-29; byte=E3'],
    ['Check the relationship', 'The retained 227 minus the borrowed positional unit 256 equals -29. This explains how the low result and borrow describe the full difference.', '227-256=-29']
  ], 'The flag and destination are two consistent parts of the same unsigned subtraction account.'], ['Reading CF as the retained sign bit', 'CF reports unsigned borrow, while SF reports the top bit of the retained result. They can differ and should not be substituted for each other.'], 'What happens for 47-18? The result is 29 and CF=0. Reversing operands changes both the arithmetic difference and the unsigned-order conclusion.'),
  'signed-overflow': dive('Check the mathematical signed range before reading the sign', [
    'The retained sign bit is meaningful as the sign of the intended answer only when that answer fits. If the mathematical result exceeds the signed range, wraparound can reverse the apparent sign. OF tells the program that the signed interpretation of the stored result no longer equals the unlimited calculation.',
    'For subtraction, overflow requires operands with different signs and a retained result whose sign differs from the first operand. Derive this from examples before using it as a shortcut. Subtracting a negative can increase a positive quantity, while subtracting a positive from a negative can pass the lower boundary.'
  ], ['A subtraction with a misleading positive result', 'Use signed byte operands -110 and +30, then perform first minus second.', [
    ['Compute the intended difference', 'The mathematical answer is -140, below the signed byte minimum -128. A correct signed-byte interpretation cannot retain that answer.', '-110-30=-140'],
    ['Find the stored pattern', '-110 is 0x92. Subtracting 0x1E leaves 0x74, which reads as positive 116 in a signed byte.', '0x92-0x1E=0x74'],
    ['Separate the flags', 'OF=1 because the signed range was exceeded. CF=0 because unsigned 146 is large enough to subtract 30. SF=0 reflects the positive-looking retained pattern.', 'OF=1; CF=0; SF=0']
  ], 'The apparent sign of the stored result can contradict the intended difference precisely when signed overflow occurred.'], ['Using SF alone for signed less-than', 'A negative mathematical difference can wrap to a clear sign bit. Signed-order conditions must account for OF as well.'], 'Would the same subtraction overflow a signed word after proper sign extension? No. -140 lies comfortably in the word range, so the wider result preserves its negative meaning.'),
  'zero-and-sign': dive('State the width when describing zero and sign', [
    'ZF tests every retained destination bit for zero. SF copies the highest retained bit for the operation’s width. The same low byte can therefore have different sign implications when interpreted as part of a larger word. A flag explanation that omits operand width is incomplete.',
    'Neither flag records an unlimited mathematical result. A wrapping sum can leave zero while an extra carry exists. A nonzero wider register can contain a zero low byte. The instruction width selects the region from which these flags are calculated. Check that region directly when interpreting the result.'
  ], ['Compare byte and word addition', 'Run two independent operations, starting from the numeric value 255 and adding one at different widths.', [
    ['Use a byte destination', 'AL begins FF. Adding one leaves 00, so ZF=1 and SF=0. CF=1 records the unsigned bit that did not fit.', '8-bit result=00; ZF=1; CF=1'],
    ['Use a word destination', 'AX begins 00FF. Adding one leaves 0100, a nonzero word with a clear highest bit. No word carry occurs.', '16-bit result=0100; ZF=0; SF=0; CF=0'],
    ['Explain the low-byte coincidence', 'Both results have a zero low byte, but the word result includes another set bit. Its zero flag therefore differs even though observing only AL would show the same byte.', 'low byte=00 in both cases']
  ], 'Interpret each flag using the complete destination width of the operation that produced it.'], ['Treating ZF as proof that the full mathematical answer was zero', 'The byte case had mathematical answer 256. ZF correctly reports the retained zero while CF reports the discarded high contribution.'], 'What is SF for the word pattern 0x0080? Zero, because bit 15 is clear. The same 0x80 as a byte has SF=1 because bit 7 is its highest position.'),
  'capture-flags-before-clobbering': dive('Name the producer of every consumed flag', [
    'Flags have a lifetime just like register values. A condition remains useful only until an instruction replaces the relevant flags. A later branch or SETcc observes the current state established by the most recent relevant flag-writing instruction.',
    'Capturing a condition turns it into ordinary data. SETC can store a carry result in a byte before unrelated arithmetic begins. That byte still needs preservation, but it is no longer vulnerable to every later flag update. Capture multiple needed conditions while the original producer remains current.'
  ], ['Preserve a carry across unrelated work', 'Add byte values 245 and 20, then increment a separate word counter with ADD.', [
    ['Produce the original condition', 'The byte sum is 265, leaving 9 and CF=1. This carry belongs to the byte addition.', 'AL=9; CF=1'],
    ['Capture before replacing', 'SETC BL writes one to BL without changing the arithmetic flags. Now the carry decision has an ordinary stored representation.', 'BL=1'],
    ['Perform the other arithmetic', 'If CX was 6, ADD CX, 1 produces 7 with CF=0. A later carry test sees this new zero, while BL still records the earlier carry.', 'CX=7; current CF=0; saved BL=1']
  ], 'The trace should identify both the current flag producer and any saved historical condition.'], ['Inserting a diagnostic ADD before SETC', 'The observation then captures the diagnostic operation’s carry. Capture the original carry before the diagnostic ADD to preserve the intended observation.'], 'Could MOV DX, AX appear between the original ADD and SETC? Yes, MOV preserves arithmetic flags. The source and destination must still be chosen so no needed data value is overwritten.'),
  'increment-and-decrement': dive('Instruction substitutions must preserve flag behavior too', [
    'Two instructions can compute the same destination bits while offering different surrounding behavior. INC and ADD by one are a useful example: INC preserves CF, while ADD calculates a new carry. Choosing between them depends on whether the next operation needs the old carry or the carry from this increment.',
    'Preserving a flag is not the same as setting it to the mathematically expected value for the new result. If CF was one before an INC that does not wrap, it remains one afterward. This can be intentional in a multiword sequence or surprising when the programmer assumes CF always describes the latest arithmetic.'
  ], ['Compare identical results with different carries', 'Start each case with AX=0xFFFF and CF=0.', [
    ['Increment with INC', 'INC AX wraps the word to zero but leaves CF unchanged at zero. Other arithmetic flags reflect the increment according to the instruction definition.', 'AX=0000; CF=0'],
    ['Increment with ADD', 'ADD AX, 1 also leaves zero, but its unsigned sum needed a seventeenth bit, so CF becomes one.', 'AX=0000; CF=1'],
    ['Feed a high word', 'A following ADC DX, 0 increments DX only in the ADD case. The INC version therefore fails as a two-word increment when the low word wraps.', 'high carry propagated only after ADD']
  ], 'Equivalent numerical destinations do not guarantee equivalent instruction sequences.'], ['Using INC to generate a new carry chain', 'INC deliberately preserves the incoming carry, so it cannot supply the newly required low-word carry to ADC.'], 'When could INC be useful between two carry-dependent steps? When a separate counter must change while an already established CF must survive. Verify that no other needed flags are being relied on.'),
  'add-with-carry': dive('Treat carry as an explicit input to the next digit', [
    'A multiword number uses positional notation with base 65536. The low word represents units, and the high word represents groups of 65536. Adding two low words can produce one extra group. ADC adds that group into the high-word calculation through its CF input.',
    'For two full multiword operands, the high operation adds both the other high word and the carry. It is not limited to adding zero. A trace should distinguish the intermediate carry entering the high word from the final carry leaving the complete result; they answer different range questions.'
  ], ['Add two two-word quantities', 'Add 0x0002:FFF0 and 0x0003:0030, retaining a 32-bit result in two word pieces.', [
    ['Add the low words', 'FFF0+0030 equals 10020. Retain 0020 and carry one positional unit into the high calculation.', 'low=0020; CF=1'],
    ['Add high words with that input', 'ADC computes 0002+0003+1=0006. The carry is counted exactly once, alongside the explicit high-word operand.', 'high=0006; final CF=0'],
    ['Verify the complete result', 'The combined answer is 0006:0020. Ordinary ADD of the high words would give 0005:0020, exactly 65536 too small.', 'correct=00060020']
  ], 'Carry is the connection between positional pieces, so preserving it is part of preserving the number.'], ['Clearing a temporary with XOR between ADD and ADC', 'XOR changes flags and clears CF. Even if the temporary value is harmless, the arithmetic chain is broken.'], 'Does the low-word carry imply the full 32-bit sum overflowed? No. Here the high word absorbed it and the final CF is zero.', flow('Add a number in word pieces', 'Each word consumes the previous carry and produces the next one.', [['start','Begin with low words','No prior piece contributes a carry.'],['low','ADD low words','Retain sixteen bits and produce CF.'],['save','Preserve pending CF','Use only suitable operations before its consumer.'],['high','ADC next words','Add both word inputs and the incoming carry.'],['more','More words remain?','The carry belongs to the next position.','decision'],['done','Record final carry','This describes overflow beyond the whole number.','terminal']], [['start','low'],['low','save'],['save','high'],['high','more'],['more','save','Yes'],['more','done','No']], 'A carry inside the number is different from a carry beyond its final word.')),
  'subtract-with-borrow': dive('Pay each borrowed positional unit exactly once', [
    'Subtraction across words follows the same positional account as addition. If the low word is too small, it borrows one group of 65536 from the next word. SBB subtracts that borrowed group as an extra one from the high-word difference.',
    'The final borrow indicates whether the complete unsigned first operand was smaller than the second. An intermediate borrow may be satisfied by a higher word and disappear from the final result. This is why inspecting only the first SUB cannot classify the whole multiword subtraction.'
  ], ['Subtract across a word boundary', 'Compute 0x0008:0010 minus 0x0002:0030.', [
    ['Subtract the low words', '0010-0030 equals -0x20, so the retained word is FFE0 and CF=1. One higher positional unit was needed.', 'low=FFE0; borrow=1'],
    ['Pay the borrowed unit', 'SBB computes 0008-0002-1=0005. This high difference fits without needing another borrow.', 'high=0005; final CF=0'],
    ['Check the whole answer', 'The result is 0005:FFE0. Omitting the borrow payment would produce 0006:FFE0, one full word position too large.', 'correct=0005FFE0']
  ], 'The low result, intermediate borrow, and final borrow each have a distinct role in the explanation.'], ['Reversing the carry input of SBB', 'SBB subtracts CF. It does not add CF or interpret it as the inverse of a borrow flag on x86.'], 'What changes if the complete starting value is zero and you subtract one? Every word must borrow, the retained result becomes all ones, and the final CF reports unsigned underflow beyond the whole number.'),
  'boundary-tests-and-explanations': dive('Choose cases that force the mechanism to matter', [
    'A test is useful when an incorrect implementation predicts a different result from the correct one. A broken carry chain can pass thousands of increments that never wrap the low word. One carefully chosen boundary case distinguishes the implementations immediately.',
    'Pair the boundary with neighboring cases. This prevents a patch that handles only the memorized failing input. Include preservation and output checks too: a correct high-word calculation can still be reported incorrectly if preparing the low-word printer argument overwrites a needed value.'
  ], ['Design a small multiword increment table', 'Consider a 32-bit quantity represented by high and low words, with high initially 0x0017.', [
    ['Test just before wrap', 'Low FFFE should become FFFF while high remains 0017. This verifies ordinary low-word progress without a carry.', '0017:FFFE -> 0017:FFFF'],
    ['Test the crossing', 'Low FFFF should become 0000 and high should become 0018. A high ADD by zero ignores the pending carry and fails exactly here.', '0017:FFFF -> 0018:0000'],
    ['Test after the crossing', 'Low 0000 should become 0001 with high unchanged. This catches an unconditional high-word increment disguised as a repair.', '0017:0000 -> 0017:0001']
  ], 'The three cases separate correct propagation from both a missing carry and an always-applied carry.'], ['Adding random cases without a reason', 'Random inputs may miss a narrow boundary. Start with cases derived from the mechanism, then add broader sampling if it answers another question.'], 'Which additional case checks overflow of the whole number? FFFF:FFFF plus one should retain 0000:0000 with final carry one. That is different from an internal carry absorbed by a nonmaximum high word.')
};

assemblyDepth['assembly-memory'] = {
  'memory-is-bytes': dive('Give addresses and contents separate columns', [
    'An address identifies a storage position; its contents are whatever byte currently occupies that position. Incrementing an address chooses a neighbor, while incrementing the contents changes a value in place. A trace that writes both in one column can accidentally turn a data change into pointer movement.',
    'Memory has no inherent word boundaries for ordinary loads. A word view groups two consecutive bytes beginning at the selected address. The same bytes can participate in several overlapping views, so your data format must identify which grouping is meaningful. Hardware acceptance alone does not define the application’s element boundaries.'
  ], ['Read overlapping views of three bytes', 'Suppose addresses 0x0640, 0x0641, and 0x0642 contain 0x19, 0xA2, and 0x37.', [
    ['Read a single byte', 'A byte load from 0x0641 returns A2. The address remains 0641 and the stored byte remains A2 after the copy.', 'address=0641; value=A2'],
    ['Read a word from the start', 'A word load beginning at 0640 uses 19 as its low byte and A2 as its high byte, giving A219.', 'word at 0640=A219'],
    ['Move the starting address', 'A word load beginning at 0641 combines A2 and 37 into 37A2. No stored byte changed; only the grouping selected by the access changed.', 'word at 0641=37A2']
  ], 'A memory explanation requires both a starting address and an access width.'], ['Assuming a label fixes all future access widths', 'A label names a position. The instruction decides how many bytes to read or write from there.'], 'If the byte at 0641 changes to 55, which word views change? Both: the first becomes 5519 and the second becomes 3755, because the views overlap at that byte.'),
  'declarations': dive('Compute data layout before execution begins', [
    'A declaration contributes bytes to the image at assembly time. Labels name positions in that layout, and the next declaration starts after the bytes already emitted. No hidden length or type field appears unless the source explicitly declares one. This makes layout a calculation you can perform before the processor runs.',
    'Runtime stores change the loaded memory copy. They do not alter the declaration in the editor or automatically persist into a future boot. Keeping these timelines separate explains why a modified variable can return to its initial value after a fresh image is loaded.'
  ], ['Lay out a compact record', 'Suppose a record begins at offset 0x7D80 and declares one byte 0x06, one word 0x2B91, and two bytes 0x44 and 0x55.', [
    ['Place the first field', 'The initial DB occupies one location. The following word therefore begins at 7D81, even though that is an odd address.', '7D80: 06'],
    ['Place the word and trailing bytes', 'DW emits 91 then 2B. The next DB values occupy 7D83 and 7D84, giving a total record size of five bytes.', '06 91 2B 44 55'],
    ['Contrast a runtime change', 'A byte store of 09 at the first field changes the loaded record. Reloading the unchanged binary restores its original 06 initialization.', 'runtime first byte=09; image first byte=06']
  ], 'The image layout and its mutable in-memory instance are related but separate objects.'], ['Expecting DW to insert alignment automatically', 'This sequence places the word immediately after one byte. Add explicit padding when a format or interface requires aligned fields.'], 'Would replacing DW 0x2B91 with DB 0x91, 0x2B change these bytes? No. The emitted representation is identical even though the source expresses it differently.'),
  'little-endian': dive('Reconstruct significance from increasing addresses', [
    'Endianness connects byte order in memory to positional significance in a multi-byte number. In a little-endian word, the first byte contributes units and the second contributes multiples of 256. The usual hexadecimal display writes the higher contribution first, which makes the displayed digit order appear reversed relative to an address-ordered dump.',
    'The address order assigns significance to whole bytes while preserving the bits inside each byte. A byte value 0x96 retains the bit pattern 10010110 whether it is the high or low byte of a word. Reversing its individual bits would be a different transformation with a different numerical result.'
  ], ['Read, modify, and reconstruct a word', 'Memory at p contains 0x6E and memory at p+1 contains 0xC2.', [
    ['Assign positional weights', 'The low byte contributes 110. The high byte contributes 194 times 256. Their sum is 49774, hexadecimal C26E.', 'word=0x6E+256*0xC2=0xC26E'],
    ['Replace only the high byte', 'Writing 0x31 at p+1 changes the higher contribution while preserving the low byte. A later word load therefore yields 316E.', 'memory: 6E 31; word=316E'],
    ['Check the reverse direction', 'To store word 0x8D07, place 07 at the lower address and 8D at the next address. Reconstructing them gives the original word.', '0x8D07 -> 07 8D']
  ], 'The significance equation gives a reliable check for either a load or a store.'], ['Reversing a character string as though it were one word', 'A byte string is an ordered sequence of independent character codes. Its interpretation does not require reversing adjacent characters merely because the CPU is little-endian.'], 'What byte pair stores the word 0x0048? It is 48 00. A word printer reads 0048, while a zero-terminated character reader may interpret those same bytes as the string H.'),
  'label-or-value': dive('An address can be data without being dereferenced', [
    'Dereferencing means using an address to access the memory it identifies. Loading a label value into a register does not dereference it. This is useful when preparing a pointer for a later operation, but it produces a different value from loading the contents currently stored at that address.',
    'A pointer is itself represented by bits and can be copied, compared, or printed. Its meaning as a location comes from how subsequent instructions use it. A hexadecimal address on screen therefore does not prove that the pointed-to data was ever read.'
  ], ['Distinguish a pointer from its target', 'Assume item names offset 0x7E10, DS is zero, and the two stored bytes there are 0xB4 and 0x29.', [
    ['Load the address value', 'MOV AX, item gives AX=7E10. The stored bytes B4 and 29 do not contribute to this result because there is no memory read.', 'AX=7E10'],
    ['Load the target word', 'MOV AX, [item] reads those two bytes and forms 29B4. The brackets change the source from an immediate address value to memory contents.', 'AX=29B4'],
    ['Read a selected source byte', 'MOV AL, [item+1] loads 29 into AL. Its source position does not make it land in AH; the destination name still selects the destination bits.', 'AL=29; AH retains its prior value']
  ], 'Address selection, dereferencing, source width, and destination region are separate decisions.'], ['Assuming brackets merely decorate a variable name', 'Removing them changes whether memory is accessed at all. Both forms can assemble successfully while computing entirely different values.'], 'If item’s stored word changes at runtime, which instruction’s result changes? The bracketed load changes; the immediate address load remains tied to item’s location.'),
  'load-store': dive('Trace the temporary between two memory locations', [
    'A normal MOV with an explicit memory operand still follows destination-first order. Loads copy from memory into a register; stores copy from a register into memory. Keeping the intermediate register visible separates source selection from destination selection when copying a value between two locations.',
    'The copy is a snapshot. If the source memory later changes, the destination does not update automatically. Likewise, changing the temporary after the store does not rewrite either memory location. Every new change requires another executed instruction directed at that storage.'
  ], ['Copy a word and then change its source', 'Suppose source contains 0x73A5 and target contains 0x0000.', [
    ['Load the snapshot', 'MOV AX, [source] reads 73A5 into AX. Target is still zero because no store has reached it yet.', 'AX=73A5; target=0000'],
    ['Store the snapshot', 'MOV [target], AX writes A5 then 73 into target’s two bytes. Source remains 73A5 and AX retains its copy.', 'source=73A5; target=73A5'],
    ['Change source independently', 'A later word store of 18C2 to source changes only source. Target still holds the earlier snapshot, making the absence of an ongoing link visible.', 'source=18C2; target=73A5']
  ], 'The temporary forms a useful observation point between the read and write stages.'], ['Writing two explicit memory operands in ordinary MOV', 'NASM cannot encode that ordinary form. Use a register temporary or an appropriate specialized copy instruction with its own contract.'], 'If target has the wrong value but AX was correct just before the store, where should you investigate next? The destination address, selected segment, width, and whether that store actually executed.'),
  'operand-width': dive('Include neighboring bytes in the expected result', [
    'A store affects the complete byte range selected by its starting address and width. Width determines how many consecutive bytes are replaced. When an immediate source gives no register-width clue, a size qualifier such as BYTE or WORD tells NASM which operation you intend.',
    'A useful test protects a neighboring byte with a distinctive marker. If an over-wide store clears or replaces that marker, the error becomes visible even when the intended low byte looks correct. This idea later becomes a guard value around a buffer, but the byte-level reasoning is the same.'
  ], ['Compare two writes at the same address', 'Begin with four bytes at p containing 0xD2, 0x6A, 0x91, and 0xE4. Evaluate each case independently.', [
    ['Write one byte', 'MOV BYTE [p], 0x38 replaces only D2. The remaining bytes preserve all their initial values.', '38 6A 91 E4'],
    ['Write one word', 'MOV WORD [p], 0x0038 writes 38 followed by 00, replacing both D2 and 6A. The low byte looks identical to the first case.', '38 00 91 E4'],
    ['Move the word store by one', 'MOV WORD [p+1], 0x0038 replaces the second and third bytes. Its range crosses whichever logical field boundary the format may place there.', 'D2 38 00 E4']
  ], 'Address and width together determine the complete write set; the declaration cannot enforce a narrower runtime boundary.'], ['Checking only the target’s first byte', 'Both a correct byte store and an incorrect word store can leave that byte equal to 38. Inspect the preserved neighbors too.'], 'How many bytes must a buffer contain for a word store at offset three to fit? At least five, because the operation touches offsets three and four.'),
  'partial-register': dive('A memory load does not erase unrelated register history', [
    'The destination view has the same behavior whether the source is immediate, another register, or memory. A load into AL replaces eight bits. If the next operation reads AX, its argument also includes the old AH. Correct memory selection alone therefore does not guarantee a correct wider value.',
    'Choose zero extension or sign extension from the field’s meaning. Clearing AX before a byte load can implement unsigned widening, but its flag effects depend on how you clear it. MOVZX directly expresses the conversion while preserving arithmetic flags, which matters when a comparison result is still live.'
  ], ['Widen a stored unsigned sample', 'Memory sample contains 0xA7 and AX initially contains 0x4C12.', [
    ['Perform a byte-only load', 'MOV AL, [sample] produces 4CA7. The low byte is correct, but the word still contains the unrelated high byte 4C.', 'AX=4CA7'],
    ['Construct the unsigned word', 'MOVZX AX, BYTE [sample] produces 00A7, preserving the intended nonnegative value 167 without depending on old AH.', 'AX=00A7=167'],
    ['Contrast the signed contract', 'If the field represents a signed byte, MOVSX produces FFA7, meaning -89. The same source bytes support a different valid conversion under that contract.', 'AX=FFA7=-89']
  ], 'A wider consumer requires all of its input bits to be deliberately defined.'], ['Clearing AX after the byte load', 'That destroys the newly loaded byte as well. Initialization must precede the narrow load, or a single extension instruction must construct the whole result.'], 'Which input would fail to expose a stale high byte if AH happened to be zero? Every unsigned byte would appear correct in that one initial state. Vary AH to test independence from prior register history.'),
  'owned-memory': dive('Validate the entire access interval', [
    'A buffer’s half-open range includes its first byte and excludes the address immediately after its end. This notation makes lengths easy to calculate: end minus start is the number of bytes. A multi-byte access fits only when every byte it touches lies inside the owned region.',
    'Ownership is a software fact. A real-mode address may be physically reachable yet belong to active code, a return address, firmware state, or a device. Declaring a buffer supplies a small region with a clear purpose, but it does not grant ownership of its neighbors.'
  ], ['Check a word access near the end', 'A declared eight-byte buffer occupies addresses b through b+7.', [
    ['Check an interior word', 'A word starting at b+5 touches offsets five and six. Both are within the eight-byte allocation.', 'range [b+5, b+7) fits'],
    ['Check the final complete word', 'A word starting at b+6 touches six and seven. Its exclusive end equals the buffer’s exclusive end, which is valid.', 'range [b+6, b+8) fits'],
    ['Reject an incomplete fit', 'A word starting at b+7 touches seven and eight. The first byte is owned but the second is outside the buffer.', 'range [b+7, b+9) does not fit']
  ], 'Checking only the starting pointer misses accesses that cross the end boundary.'], ['Calling nearby memory free because a store succeeds', 'The CPU may execute the write without diagnosing the software ownership error. The damage can appear later when another component uses the overwritten bytes.'], 'How can you check a width w without overflowing start+w? When the offset is already known valid, compare w with the remaining length. The exact implementation must still preserve the required arithmetic width.', flow('Validate before touching memory', 'Address formation and ownership checks answer different questions.', [['form','Compute start and width','Record the complete byte interval.'],['owned','Is the start owned?','Identify the buffer or component responsible for it.','decision'],['fit','Does the full operand fit?','Check every byte covered by the operand width.','decision'],['access','Perform the load or store','Use the verified width and address.'],['reject','Reject or choose another range','Do not access bytes outside the agreed region.','terminal']], [['form','owned'],['owned','fit','Yes'],['owned','reject','No'],['fit','access','Yes'],['fit','reject','No']], 'A syntactically valid memory operand can still violate the program’s storage contract.')),
  'memory-experiment': dive('Make the store observable with a fresh reload', [
    'Printing the register used for a store does not prove that the memory write reached the intended location. The register already contained the value before the store. A stronger experiment discards that register value and reloads from the destination, so the observation depends on memory.',
    'Use unequal input bytes and a destination initialized differently from the expected answer. Equal bytes hide reversals, and a destination that already contains the answer hides a missing store. Good inputs make plausible incorrect paths visibly different from the intended path.'
  ], ['Reconstruct, store, discard, reload', 'Two source bytes are 0x47 and 0xD3. A separate two-byte destination begins as zero.', [
    ['Construct the word deliberately', 'Load 47 into AL and D3 into AH. This produces D347; reading the first source byte twice would produce 4747.', 'AX=D347'],
    ['Store to the destination', 'The word store writes 47 then D3. The destination’s address-ordered dump now records the reconstructed value.', 'destination bytes: 47 D3'],
    ['Remove the register shortcut', 'Set AX to zero before loading it from the destination. A resulting D347 now depends on the destination memory because the old register value was explicitly cleared.', 'AX=0000 -> reload -> D347']
  ], 'Each stage has an independent observable consequence, so a failure can be localized to construction, storage, or retrieval.'], ['Hard-coding the reconstructed value', 'That reproduces one visible answer but breaks the required data dependency. Changing the input should change the result through the same mechanism.'], 'What input variation exposes a swapped-byte implementation? Any unequal pair, such as 28 and B6, because the correct B628 differs from the swapped 28B6.'),
  'memory-explain': dive('Predict a mutation by drawing its exact byte footprint', [
    'Before running a memory edit, write the initial address-ordered bytes and mark every position the store replaces. Then reconstruct any wider values that later reads will observe. This separates the mutation from its later interpretation and works even when multiple fields share the affected region.',
    'The method also explains aliases: two labels or pointers can refer to overlapping bytes. A write through one name can change the value observed through another without either name appearing in the same instruction. Draw the overlapping byte ranges to explain how the write affects each view.'
  ], ['Explain an overlapping word mutation', 'Three bytes at p are 0x32, 0xA8, and 0x5D. Consider word views beginning at p and at p+1.', [
    ['Read both initial views', 'The first word is A832. The second is 5DA8. They overlap at the middle byte A8.', 'at p=A832; at p+1=5DA8'],
    ['Replace the shared byte', 'A byte store of 0x71 at p+1 changes only the middle byte, yielding 32 71 5D.', 'memory: 32 71 5D'],
    ['Reconstruct both results', 'The first word becomes 7132 because its high byte changed. The second becomes 5D71 because its low byte changed.', 'at p=7132; at p+1=5D71']
  ], 'One byte write can change several overlapping interpretations while touching only one physical location.'], ['Reasoning only from variable names', 'Different labels do not guarantee disjoint storage, and one label does not guarantee one access width. Draw the addressed bytes when overlap matters.'], 'Would a word store at p+1 have the same effect? No. It would also replace the byte at p+2, so the second word’s high byte would change as well.')
};

assemblyDepth['assembly-addressing'] = {
  'address-stages': dive('Write the address calculation as a pipeline', [
    'An effective offset is only one stage of a real-mode memory address. First evaluate the legal address expression at its address width. Next select the segment register, derive its base, and combine that base with the offset. Finally, use operand width to identify the complete accessed range.',
    'Keeping these stages separate gives each possible error a place in the trace. A correct offset can still pair with the wrong segment. A correct starting byte can still begin an over-wide access. The low-address examples here avoid A20 and segment-end complications so the ordinary pipeline remains explicit.'
  ], ['Resolve a two-byte data access', 'Assume DS=0x1340, BX=0x0020, SI=6, and the instruction reads a word through [bx+si+2].', [
    ['Compute the effective offset', 'Add the register values and displacement: 0x20+6+2=0x28. The sum supplies the offset. The selected segment will supply the base in the next stage.', 'effective offset=0x0028'],
    ['Select and expand the segment', 'This BX-based form normally uses DS. Real-mode DS=1340 contributes base 0x13400.', 'selected segment=DS; base=0x13400'],
    ['Apply the access width', 'Adding the offset gives start 0x13428. The word load reads bytes at 13428 and 13429, which must both belong to the intended data region.', 'accessed bytes: 0x13428, 0x13429']
  ], 'The result is an accessed interval with a justified segment and offset, with every stage of the address calculation accounted for.'], ['Adding the segment value without multiplying by sixteen', 'DS contains the segment value; multiply it by sixteen to obtain the base. Omitting that conversion selects a completely different location.'], 'If SI increases by two while DS stays fixed, how does this access move? Its start increases by two bytes, provided the effective offset does not wrap.'),
  'alias-pairs': dive('Prove whether two pointers identify the same bytes', [
    'Two segment:offset pairs alias when their base-plus-offset calculations produce the same location. Aliasing means different pointer representations can still observe or modify shared storage. Comparing the segment and offset fields separately therefore does not establish whether the underlying bytes are distinct.',
    'The representation is flexible because real-mode segment bases advance in sixteen-byte steps while offsets cover many such steps. Coordinated changes can preserve the total. An uncoordinated change cannot: increasing the segment without compensating the offset moves the actual address.'
  ], ['Construct an equivalent pair', 'Begin with segment:offset 1420:0068 and keep the result below one MiB.', [
    ['Compute its location', 'The segment base is 0x14200. Adding offset 0x68 gives physical address 0x14268.', '1420:0068 -> 0x14268'],
    ['Move the segment by three', 'Increasing the segment to 1423 moves its base forward 0x30 bytes. Decrease the offset by the same 0x30 to 0038.', '1423:0038 -> 0x14268'],
    ['Check the uncompensated version', '1423:0068 produces 0x14298. Keeping the old offset does not preserve the original byte.', 'uncompensated difference=0x30']
  ], 'To establish equivalent notation, calculate both base-plus-offset results and compare their complete values.'], ['Treating separate segments as automatic allocations', 'Different segment values can still produce overlapping physical regions. Use a memory map to establish ownership and show whether the addressed regions overlap.'], 'If one alias writes a byte, what should the other alias read afterward? The new byte, because both identify the same storage; the differing representation does not create a copy.'),
  'legal-forms': dive('Separate a desired formula from an encodable address', [
    'The mathematical expression for an address may be more general than a particular x86 address form. Sixteen-bit addressing offers a fixed menu of registers and pairs. NASM can simplify constants, but it cannot silently invent extra runtime instructions to evaluate an unsupported combination inside brackets.',
    'When the formula is not directly encodable, calculate a suitable offset in ordinary instructions and place it in an allowed address register. Those extra operations have their own register and flag effects, which must be included in the surrounding data-flow plan.'
  ], ['Translate a formula into legal steps', 'The desired offset is AX+CX+4, and BX is available as scratch storage.', [
    ['Identify the unsupported form', 'A memory operand [ax+cx+4] is not part of the sixteen-bit addressing menu. The arithmetic intention is understandable, but that encoding does not exist.', 'desired offset=AX+CX+4'],
    ['Compute into a legal register', 'Copy AX into BX and add CX to BX. Then a memory operand [bx+4] uses the computed sum plus the displacement.', 'BX receives AX+CX'],
    ['Account for side effects', 'The ADD changes arithmetic flags and BX loses its earlier value. If either was live, preserve it or reorganize the calculation before using this plan.', 'address form [bx+4] is encodable']
  ], 'An assembler error can reveal a mismatch between the algorithm’s formula and the architecture’s available operand forms.'], ['Borrowing a scaled-index example from another address size', 'A sixteen-bit [si*2] form is not available merely because a wider x86 mode offers scaled indexes. Keep the address-size assumption explicit.'], 'Can BX+DI+6 be encoded directly with sixteen-bit addressing? Yes. It uses an allowed base/index pair and a constant displacement, normally selecting DS.'),
  'default-segment': dive('Annotate the segment even when its current value is zero', [
    'The address form determines a memory operand’s default segment according to architectural rules. In the sixteen-bit forms here, BP-based addressing normally selects SS, while BX-based ordinary data addressing selects DS.',
    'Equal initial segment values can hide an incorrect assumption because both calculations happen to reach the same location. A paper trace with unequal segments exposes the dependency without disrupting the active runtime stack. This is a useful distinction between a controlled thought experiment and a safe live edit.'
  ], ['Hold offsets equal while changing the selected base', 'Assume DS=0x1260, SS=0x1A40, BX=BP=0x0050, and DI=8.', [
    ['Compute the common offset', 'Both BX+DI and BP+DI give 0x0058. Offset arithmetic alone cannot distinguish the accesses.', 'effective offset=0058'],
    ['Resolve the data-based form', 'The ordinary [bx+di] operand uses DS, giving 0x12600+0x58=0x12658.', '[bx+di] -> 0x12658'],
    ['Resolve the frame-based form', 'The [bp+di] operand uses SS, giving 0x1A400+0x58=0x1A458. Equal general-register values still select different storage.', '[bp+di] -> 0x1A458']
  ], 'The segment selection is part of the operand’s meaning even when a simple harness makes it invisible.'], ['Changing SS casually to demonstrate the rule', 'The active stack and saved return address also depend on SS. Use the differing-segment calculation on paper unless the entire stack transition is deliberately managed.'], 'Why might an accidental BP-based data access pass an early test? The harness initializes DS and SS equally, so the wrong default base can temporarily produce the intended physical address.'),
  'segment-override': dive('Change the selected base without changing stored segment state', [
    'A segment override applies to the relevant memory access in one instruction. It chooses which existing segment register contributes the base. It neither loads that register nor permanently changes the default for later instructions. This local scope lets a BP-based calculation deliberately access a data region.',
    'An override cannot repair an uninitialized segment value by itself. Selecting DS explicitly is useful only if DS already describes the intended data base. Trace an override by selecting the named segment register’s current value as an input to the address calculation.'
  ], ['Compare an overridden read and the following ordinary read', 'Assume DS=0x1550, SS=0x2110, and BP=0x0036.', [
    ['Use the usual BP default', 'A word read from [bp+4] selects SS and effective offset 003A, beginning at 0x2113A.', 'default start=0x2113A'],
    ['Override this access', 'A word read from [ds:bp+4] retains offset 003A but selects DS, beginning at 0x1553A.', 'overridden start=0x1553A'],
    ['Read again without an override', 'A later [bp+4] uses SS again. The prior override did not modify SS, DS, BP, or the general default rule.', 'next default start=0x2113A']
  ], 'The instruction changes which segment value participates, while the segment registers themselves remain unchanged.'], ['Assuming an override is persistent setup', 'Repeating an access without its required override can select a different base. Include the choice at each access that needs it.'], 'If DS contains the wrong value, does writing [ds:bp+4] fix the pointer? No. It makes the selected register explicit, but its contents must still satisfy the address contract.'),
  'origin-contract': dive('Make the loader, label values, and segment base agree', [
    'ORG contributes an assumed starting value to assembled addresses in a flat binary. The loader independently decides where the bytes actually appear. Runtime segment state then determines what physical location a label-valued offset reaches. A correct design makes all three accounts identify the same bytes.',
    'A relative branch can conceal a placement mismatch because both its start and destination shift together. An absolute data reference retains the assembler’s assumed address and can fail first. Thus correct execution of several jumps does not prove that every label-based memory access is properly relocated.'
  ], ['Diagnose a misplaced image', 'A flat image uses ORG 0x7C00 and a data label lies 0x90 bytes into the file.', [
    ['Derive the assembled label', 'NASM assigns the label value 0x7C90. That is the offset a direct label reference will use under this layout.', 'label=0x7C00+0x90=0x7C90'],
    ['Use the intended placement', 'If the image begins physically at 0x7C00 and DS=0, the reference reaches the actual data at 0x7C90.', 'expected load -> data at 0x7C90'],
    ['Compare a changed loader placement', 'If the unchanged bytes are loaded at 0x8000, the actual data is at 0x8090. The old DS:label reference still reaches 0x7C90 and reads somewhere else.', 'actual data=8090; referenced=7C90']
  ], 'ORG establishes the artifact’s address arithmetic. The loader and segment setup must establish matching runtime locations.'], ['Trying to fix loading by editing only ORG', 'A changed origin does not move the file or initialize segments. Check all components of the address agreement together.'], 'Why could an internal short jump still work after the move to 8000? Its encoded displacement depends on the distance between nearby instructions, which can remain unchanged when the whole image shifts.'),
  'lea': dive('Compute a location without performing the access', [
    'LEA reuses address-expression syntax to calculate an effective offset. It does not fetch the memory bytes at that offset and does not include the real-mode segment base in the result. This makes it useful for preparing a pointer that another instruction will later dereference.',
    'It also preserves arithmetic flags, unlike ordinary ADD-based address arithmetic. That can matter when a comparison result must survive across pointer preparation. Preserving flags does not imply preserving destination registers, so the chosen destination still needs to be disposable or deliberately saved.'
  ], ['Separate pointer preparation from loading', 'Let BX=0x0300, DI=10, DS=0x1200, and suppose the word at physical 0x1230C is 0x6F28.', [
    ['Calculate the offset', 'LEA SI, [bx+di+2] computes 0300+000A+2=030C. It does not read 6F28 from memory.', 'SI=030C'],
    ['Interpret the pointer in context', 'A later ordinary [si] access uses DS and reaches 0x12000+0x030C=0x1230C. The segment contributes only when that memory access is formed.', 'DS:SI -> 0x1230C'],
    ['Load the contents explicitly', 'MOV AX, [si] then reads the word 6F28. Pointer creation and data retrieval are two distinct executed operations.', 'AX=6F28']
  ], 'The brackets describe an address expression, while the instruction definition determines whether memory is accessed.'], ['Calling the LEA result a physical address', 'In this form it is the effective offset. Adding a nonzero segment base is a separate stage of a later memory reference.'], 'Could changing the bytes at 0x1230C change this LEA result? No. LEA computes the effective offset entirely from its register inputs and displacement.'),
  'array-stride': dive('Attach units to index arithmetic', [
    'An element index counts elements, while a byte offset counts bytes. Multiplying the index by the element size converts between those units. Forgetting the conversion can still produce an encodable address, but the resulting bytes may straddle adjacent elements.',
    'Write the units in your trace even when both quantities happen to have the same numeric value for a byte array. That habit prevents a later change from bytes to words from silently changing the meaning of the pointer update. An array’s stride belongs to its representation.'
  ], ['Locate a word by index', 'A three-word array contains 0x3A17, 0x6C29, and 0x8E4B at its base.', [
    ['Expand the representation', 'The address-ordered bytes are 17 3A 29 6C 4B 8E. Each logical element occupies two consecutive byte positions.', 'stride=2 bytes per element'],
    ['Convert the requested index', 'Index two means the third element. Multiplying by two gives byte offset four, where a word read produces 8E4B.', '2 elements * 2 bytes=4 bytes'],
    ['Explain the unscaled error', 'Using byte offset two reads 6C29, the second element. Using offset one reads 293A, which crosses the first and second words.', 'wrong offsets select different bytes']
  ], 'A wrong result often tells you exactly which unit conversion or stride was omitted.'], ['Assuming an odd word address must be rejected', 'An ordinary x86 word access can be encodable there, but it may not correspond to an intended array element. Semantic validity is a separate question.'], 'For five-byte records, where does zero-based record three begin? At base plus fifteen bytes. A field offset within that record must then be added separately.'),
  'offset-overflow': dive('Apply width before adding the segment base', [
    'Address arithmetic has finite width just like ordinary integer arithmetic. In a sixteen-bit effective-address calculation, excess high bits do not become an extra segment increment. The retained offset is formed first, and the selected segment base is combined with that retained value.',
    'A bounds proof must cover this arithmetic stage as well as the final memory width. Computing base plus length in too narrow a register can wrap before a comparison notices the problem. For these examples, keep the complete access away from segment limits so address truncation is the only changing mechanism.'
  ], ['Trace an overflowing effective offset', 'Assume DS=0x1800, BX=0xFFF0, SI=0x0030, and a byte read through [bx+si].', [
    ['Compute the unlimited sum', 'FFF0+0030 equals 10020. That needs seventeen bits and therefore does not fit the sixteen-bit effective offset.', 'full offset sum=0x10020'],
    ['Retain the offset width', 'The effective offset becomes 0020. The discarded high bit does not automatically increase DS.', 'effective offset=0x0020; DS=0x1800'],
    ['Add the selected base', 'The base is 0x18000, so the access reaches 0x18020. Adding the unlimited sum would incorrectly predict 0x28020.', 'actual start=0x18020']
  ], 'The order of truncation and base addition changes the answer and must be part of the explanation.'], ['Treating segment and offset as one unlimited integer expression', 'That hides the architectural width boundary and can predict an address the instruction never forms.'], 'Would using a smaller input offset remove every access risk? No. The resulting address still needs valid ownership, and a multi-byte operand must fit entirely within the permitted region.'),
  'addressing-evidence': dive('Use the wrong value to reconstruct the wrong access', [
    'An unexpected loaded word is often structured evidence. If its bytes match neighboring fields in the buffer, the result can reveal an off-by-one address or incorrect stride. This is more useful than treating every wrong hexadecimal number as an unrelated failure.',
    'Work backward from the observed bytes, then forward through the suspected address calculation. Agreement between both directions gives a concrete hypothesis. Test it with another asymmetric input so that a coincidental byte match does not become an unsupported diagnosis.'
  ], ['Explain an address-one result', 'An array starts with words 0x4D12 and 0x7A36. A buggy read produces 0x364D.', [
    ['Write the byte map', 'The four bytes are 12 4D 36 7A. The observed low byte 4D belongs at offset one, and high byte 36 belongs at offset two.', 'offsets 0..3: 12 4D 36 7A'],
    ['Infer the candidate access', 'A word load beginning at offset one combines exactly those two bytes into 364D. This suggests a one-byte displacement where a word stride was expected.', 'candidate start=base+1'],
    ['Check the address pipeline', 'Inspect the index-to-byte conversion, legal address form, and selected segment. Then change the data values and verify that the same mistaken range predicts the new result.', 'hypothesis: unscaled word index']
  ], 'The observation becomes explanatory when it is linked to a specific accessed range and a repeatable address calculation.'], ['Replacing the observation with a constant', 'Substituting the expected constant can hide the symptom while leaving the erroneous read and its data dependency intact.'], 'What makes two equal words a poor diagnostic input? Their repeated bytes can make several wrong offsets produce plausible values, reducing your ability to distinguish competing address hypotheses.', flow('Explain a loaded value', 'Trace the address in stages before blaming the data or the printer.', [['index','Convert index to bytes','Multiply by the representation’s stride.'],['offset','Form the effective offset','Use an encodable form and its address width.'],['segment','Select segment and base','Include defaults or an explicit override.'],['range','Does the full access fit?','Check ownership and operand width.','decision'],['read','Reconstruct selected bytes','Apply little-endian significance.','terminal'],['repair','Repair the address contract','Do not use the out-of-range operand.','terminal']], [['index','offset'],['offset','segment'],['segment','range'],['range','read','Yes'],['range','repair','No']], 'Each stage can be correct while a later stage is wrong, so record their results independently.'))
};

assemblyDepth['assembly-branches'] = {
  'instruction-pointer': dive('Draw both successors of a conditional branch', [
    'A conditional branch has two possible next positions: its destination when the condition holds and the sequential instruction when it does not. A flowchart should include both, even when one path looks like doing nothing. Fall-through is still a control-flow decision with consequences for which instructions execute.',
    'A basic block is a straight-line group with no internal branch choosing another path. Thinking in blocks makes an if/else readable: one decision selects an arm, each arm establishes its result, and both reach a shared continuation. The labels connect the blocks but do not themselves perform computation.'
  ], ['Follow a zero and nonzero case', 'A routine tests AX, sends zero to an empty arm, and otherwise uses a value-present arm.', [
    ['Trace the taken branch', 'With AX=0 and ZF established accordingly, JZ empty selects the empty label. Instructions in the skipped value-present block have no effect on this execution.', 'next block=empty'],
    ['Trace fall-through', 'With AX=7 and the corresponding nonzero result, the same JZ is not taken. Execution continues with the immediately following instruction.', 'next block=value-present'],
    ['Check the join', 'Both arms must reach the common continuation without accidentally executing the other arm. A jump from the earlier arm may be required by the chosen source layout.', 'one decision -> one arm -> join']
  ], 'The truth of the condition and the placement of the blocks are separate parts of branch correctness.'], ['Reading only the arrow labeled with the condition', 'The untaken path is an equally real successor. Omitting it can conceal accidental execution of an arm or missing initialization before the join.'], 'Can renaming the empty label change which path is taken? Not if all references are updated consistently. Changing the branch condition or target placement can change execution.'),
  'cmp': dive('Derive the flags without destroying the compared data', [
    'CMP performs the status calculation for destination minus source while leaving both operands available. Its lack of a stored difference is useful when the selected branch still needs the original value. The flags become the comparison result, and their later consumer chooses which relation to test.',
    'Read operand order aloud before selecting that relation. Equality is symmetric, but ordering is directional. Swapping operands and keeping the same less-than branch reverses the question. A numerical subtraction on paper is often the quickest way to catch this mistake.'
  ], ['Compare unequal words in both directions', 'Let AX=14 and BX=31 and consider two independent CMP instructions.', [
    ['Compare AX with BX', 'CMP AX, BX models 14-31=-17. The retained word would be FFEF, ZF is zero, and unsigned borrow makes CF one.', 'AX=14; BX=31; CF=1; ZF=0'],
    ['Keep operands intact', 'After that CMP, AX still contains 14 and BX still contains 31. The hypothetical FFEF determines the flags while AX retains its original 14.', 'no data destination changed'],
    ['Reverse the comparison', 'CMP BX, AX models 31-14=17, so CF is zero and ZF remains zero. An unsigned-below branch now answers whether 31 is below 14.', 'reversed CF=0; ZF=0']
  ], 'The unchanged operands and directional flag calculation explain why CMP is useful and why its order matters.'], ['Expecting AX to contain the difference', 'CMP does not store that result. Use SUB when the difference itself is required, while accounting for the destructive destination update.'], 'If AX and BX are equal, does reversing CMP change equality? No. Both hypothetical differences are zero, so JE tests true in either direction.'),
  'equality': dive('Use equality without inventing a signedness distinction', [
    'Equality compares complete patterns at the chosen width. Two equal byte patterns have the same signed and unsigned reading relative to each other. Ordering uses separate signed and unsigned branch families. Equality uses the same pattern-matching condition under either interpretation.',
    'The width still matters. Equal low bytes do not imply equal words if their high bytes differ. Choose a comparison that covers the actual field or quantity whose equality the program requires, then consume its ZF before another instruction replaces it.'
  ], ['Compare a narrow and a wide view', 'Let AX=0x127E and BX=0xA97E.', [
    ['Compare low bytes', 'CMP AL, BL compares 7E with 7E and sets ZF=1. JE would take its equal path for this byte-sized question.', 'AL=BL=7E; ZF=1'],
    ['Compare complete words', 'CMP AX, BX compares different high bytes as well as equal low bytes. The word patterns differ, so ZF=0.', '127E != A97E; ZF=0'],
    ['Interpret the aliases', 'JZ tests the same zero-flag condition as JE. Changing the mnemonic spelling does not expand the width or restore the earlier byte comparison’s flags.', 'JE and JZ both test current ZF']
  ], 'Equality has no signedness split, but it still needs a precisely defined operand width and flag producer.'], ['Assuming matching printed suffixes prove equality', 'A display of low bytes omits the high bytes that a word comparison includes. Align the observation width with the comparison requirement.'], 'After ADD AL, BL, what does JZ mean? It asks whether that addition’s retained byte result is zero. It does not remember any earlier equality comparison.'),
  'unsigned': dive('Derive a bounds condition from the valid interval', [
    'For an unsigned index into N elements, valid values satisfy index less than N. The invalid boundary includes equality because index N is one past the last element. This wording leads directly to an above-or-equal rejection after comparing the index with N.',
    'Separate the mathematical condition from its branch layout. A program can branch on validity into the body or branch on invalidity around it. Both layouts work if the selected mnemonic matches the arrow’s meaning and the following code preserves the intended access boundary.'
  ], ['Review a four-element bounds check', 'The valid unsigned indices are zero, one, two, and three. Compare each candidate with length four.', [
    ['Test the last valid index', 'Index three is below four. CMP sets CF=1, so JAE reject is not taken and the element access is permitted.', '3 < 4: admit'],
    ['Test the exact boundary', 'Index four compares equal, setting ZF=1 and CF=0. JAE rejects it because equality is outside the valid interval.', '4 = 4: reject'],
    ['Test a high-bit pattern', 'A word index 0xFFFE represents unsigned 65534. It is above four and must be rejected.', '65534 >= 4: reject']
  ], 'The branch includes equality because the data structure uses a half-open range.'], ['Using JA for an index-at-length rejection', 'JA excludes equality, so it would admit the first invalid index. Boundary wording determines whether equality belongs on the rejected path.'], 'When would JBE be appropriate for a maximum value? When the specification allows values up to and including that maximum. A maximum value and an exclusive length are different contracts.'),
  'signed': dive('Use overflow to correct a wrapped subtraction sign', [
    'Signed less-than asks whether the unlimited signed difference is negative. When subtraction fits, SF answers that question directly. When it overflows, the retained sign is reversed relative to the mathematical result, and OF tells the signed condition to correct it.',
    'The expression SF differs from OF is therefore a compact representation of those two overflow cases. Write one case without overflow and one with overflow to see why checking SF alone fails. Equality is handled separately when the relation includes it.'
  ], ['A positive value remains greater despite a negative-looking difference', 'Compare signed bytes +100 and -60 using CMP AL, BL.', [
    ['Compute the signed difference', '100-(-60)=160, which is positive but exceeds the maximum signed byte value 127.', 'mathematical difference=160'],
    ['Derive the retained flags', 'The byte result is A0, whose top bit is one. SF=1 and OF=1, so their equality indicates that the signed less-than condition is false.', 'SF=1; OF=1; ZF=0'],
    ['Select the signed order', 'JG requires a nonzero comparison with SF=OF, so it recognizes that +100 is greater than -60. JS alone would incorrectly follow the retained negative-looking sign.', 'signed greater=true']
  ], 'The overflow-aware relation follows the intended signed ordering even when the temporary difference cannot fit.'], ['Using the unsigned jump because the bytes look large', 'Unsigned ordering would interpret the negative operand’s pattern as a large nonnegative number. Choose the family from the data meaning.'], 'What changes for equal signed values? ZF becomes one. JGE includes them, while JG excludes them; the overflow correction does not remove the need to specify equality.'),
  'flags-lifetime': dive('Identify the current flag producer before branching', [
    'A conditional jump reads the current flags when it executes. Track the most recent instruction that produced those flags. Any intervening flag-writing instruction can change the decision, even if both comparison operands still visibly contain the expected values.',
    'A last-producer annotation makes this dependency explicit. Record which instruction most recently wrote each relevant flag. Some instructions preserve CF but replace ZF, so the answer depends on the condition being consumed. Saying an instruction preserves flags without naming which ones is too broad.'
  ], ['Expose a pointer update between comparison and branch', 'AX and BX both contain 12, while SI contains 0x0200.', [
    ['Establish equality', 'CMP AX, BX sets ZF=1 because the compared words match. At this boundary, JE would take the equal path.', 'ZF=1 from CMP'],
    ['Replace the condition accidentally', 'ADD SI, 2 produces 0202, which is nonzero. ZF becomes zero even though AX and BX are still both 12.', 'ZF=0 from ADD'],
    ['Repair the dependency', 'Place JE immediately after CMP, or use a suitable flag-preserving pointer calculation such as LEA when the layout requires the update first.', 'consume the intended producer']
  ], 'The trace identifies the cause of the wrong branch: ADD replaced the ZF produced by CMP.'], ['Using DEC as though it preserved equality', 'DEC preserves CF but updates ZF. It may be safe for one carry-based condition and unsafe for an equality condition.'], 'Could SETE DL capture the original equality before ADD? Yes. It records the condition as a byte, after which later flag changes do not alter that saved byte, provided DL itself is preserved.'),
  'test': dive('Distinguish any selected bit from all selected bits', [
    'TEST computes a temporary AND and uses it for flags without storing it back. A nonzero result means at least one bit selected by the mask was present. That is an existential question: does any selected position contain one? Checking that every requested capability is enabled requires comparing the masked value with the entire required mask.',
    'To test whether all selected bits are present, preserve the original if needed, mask a working copy, and compare that copy with the full mask. Writing the intended English question first prevents a single convenient instruction from silently changing the specification.'
  ], ['Check two independent permission bits', 'Suppose bits 1 and 4 are required, giving mask 0x12, while AX contains 0x10.', [
    ['Ask whether any required bit exists', 'TEST AX, 0x12 produces temporary 0x10. ZF=0, so JNZ is taken even though bit 1 is absent.', 'any selected bit: yes'],
    ['Ask whether all are present', 'Copy AX to BX, AND BX with 0x12, then compare BX with 0x12. The masked 0x10 does not equal the required 0x12.', 'all selected bits: no'],
    ['Preserve the original field', 'Using BX for the destructive mask leaves AX intact. TEST itself also left AX unchanged, though it did replace arithmetic flags.', 'AX remains 0x10']
  ], 'A precise bit question determines whether TEST alone supplies enough information.'], ['Reading JNZ as every masked bit is set', 'Nonzero AND only proves at least one shared set bit. A multi-bit requirement needs an equality check against the mask.'], 'What does TEST AX, AX followed by JZ ask? Whether the whole word is zero, because ANDing a pattern with itself reproduces that pattern for the flag calculation.'),
  'if-else': dive('Make the join preserve exactly one arm’s result', [
    'The join is the first shared continuation after the two alternative paths. Each incoming path should establish the values that continuation expects. If one path leaves a required result uninitialized, the source may look balanced while the runtime state depends on which arm was taken.',
    'The earlier arm often needs an unconditional jump past the later arm. Without it, a correctly selected true path can execute its own work and then overwrite the result in the false path. A diagram reveals this fall-through defect immediately.'
  ], ['Select one result for a signed threshold', 'Set DX to 1 when signed AX is below 20, otherwise set DX to 2.', [
    ['Branch on the rejecting condition', 'CMP AX, 20 followed by JGE else sends values twenty and above to the second arm. Smaller values fall through to the first arm.', 'AX=15 -> first arm; AX=20 -> else'],
    ['End the first arm deliberately', 'After MOV DX, 1, jump to done so the later MOV DX, 2 cannot overwrite it on the same path.', 'first-arm result survives: DX=1'],
    ['Check the shared continuation', 'The else arm sets DX=2 and then reaches done. Every incoming path now gives the join a defined result and executes exactly one assignment arm.', 'done receives DX=1 or DX=2']
  ], 'Correct condition selection and correct path layout are both necessary for an if/else.'], ['Testing only the later arm', 'A missing jump over else often affects only the earlier arm. Include a case for each path and the exact comparison boundary.'], 'If the first arm is moved after the else arm, can the same logical decision still work? Yes, but the branch target, inversion, and bypass jump must be adjusted to the new layout.', flow('A complete signed if/else', 'Both arms establish DX before the shared continuation.', [['compare','Compare AX with 20','CMP establishes flags for signed ordering.'],['decision','AX at least 20?','JGE selects the else arm.','decision'],['yesarm','Set DX to 2','The threshold and higher values use this result.'],['noarm','Set DX to 1','Smaller values use this result, then bypass the other arm.'],['join','Continue with defined DX','Exactly one arm has supplied the result.','terminal']], [['compare','decision'],['decision','yesarm','Yes'],['decision','noarm','No'],['yesarm','join'],['noarm','join']], 'The arrows express alternatives; the source layout must include the jumps needed to preserve them.')),
  'branch-repair': dive('Choose an input on which competing interpretations disagree', [
    'A signedness defect remains invisible when both operands are small positive patterns, because both interpretations order them identically. A discriminating test deliberately uses a high-bit pattern against a small positive value. The wrong jump family then predicts a different path.',
    'A complete repair also checks direction and equality. Changing from unsigned to signed is not enough if operands were reversed or the chosen condition includes the wrong boundary. Build a small table from the stated relation before touching the branch mnemonic.'
  ], ['Separate signed and unsigned explanations', 'The specification asks whether signed byte x is below 9. Test x with pattern 0xD6.', [
    ['Read both meanings', 'Unsigned D6 is 214, which is above nine. Signed D6 is 214-256=-42, which is below nine.', 'unsigned: 214>9; signed: -42<9'],
    ['Predict the required path', 'The signed contract requires the below path. A signed less-than condition after CMP x, 9 expresses that relation.', 'required result: below'],
    ['Check neighboring relation cases', 'Also test x=9 for equality and x=10 for the opposite order. A strictly-less condition must reject both of those cases.', '9 -> false; 10 -> false']
  ], 'The chosen input turns an interpretation error into a predictable branch disagreement.'], ['Changing only the displayed message', 'That can make one test look correct while the wrong path and all its other effects remain unchanged. Repair the condition that selects the path.'], 'What case checks reversed operand order? Use unequal small positives such as x=4 and limit=9; comparing limit against x with the same less-than jump reverses the intended answer.'),
  'branch-debug': dive('Audit the whole chain from data meaning to continuation', [
    'A branch failure can originate in the loaded value, operand width, interpretation, flag producer, condition selection, target, or later fall-through. These are separate links. Start at the earliest link for which observed state differs from the intended model, because later symptoms may merely follow from that earlier mismatch.',
    'Record enough information to reproduce the decision on paper: actual operand patterns, intended signedness, flags immediately before the jump, and both possible successors. Then trace the chosen arm through its exit. This turns debugging from mnemonic guessing into checking a finite set of claims.'
  ], ['A correct comparison followed by an incorrect result', 'A signed comparison correctly selects a smaller-value arm, but the final result still says larger.', [
    ['Verify the decision inputs', 'Use AX=-7 and BX=3. The signed relation is unambiguous, so record the flags at the conditional jump and confirm the smaller arm is entered.', '-7 < 3: smaller arm selected'],
    ['Follow the entire arm', 'Suppose that arm assigns DX=1 but then falls into the larger arm, which assigns DX=2. The comparison and branch were correct; the join layout was not.', 'DX: 1 -> 2'],
    ['Repair the first wrong control edge', 'Add or correct the bypass to the shared continuation. Then retest both arms so the repair does not redirect the other input incorrectly.', 'smaller arm -> shared continuation']
  ], 'Correct branch entry is only part of the path; follow it until its intended result is consumed.'], ['Treating a final wrong value as proof of a wrong Jcc', 'The branch may have selected the right arm. Later overwrites or unintended fall-through can produce the same visible symptom.'], 'What should a loop review add to this branch audit? It must check repeated state updates and a progress measure, because the same decision may be revisited many times.')
};

assemblyDepth['assembly-loops'] = {
  'loop-structure': dive('Give every repeated state variable one meaning', [
    'A loop reuses instruction addresses, but its data state should advance. Assign each register a sentence: SI identifies the next word, CX counts unprocessed words, and AX holds the sum of already processed words. Those meanings connect initialization, body, update, and exit into one algorithm.',
    'The body is allowed only when the next element exists. The update must account for exactly the work the body completed. If it consumes one word, the pointer advances two bytes and the remaining count decreases by one. These updates use different units but describe the same progress.'
  ], ['Build the state transitions for two words', 'Let the words be 6 and 11, with base address b and no accumulator overflow.', [
    ['Initialize the empty result', 'Before any access, AX is zero, SI is b, and CX is two. This establishes the sum of zero completed elements before the first addition.', 'completed=0; remaining=2; sum=0'],
    ['Consume one permitted word', 'Read 6, add it, advance SI to b+2, and reduce CX to one. Every state variable now describes one completed element.', 'completed=1; remaining=1; sum=6'],
    ['Consume the final word and stop', 'Read 11, giving sum 17, pointer b+4, and remaining zero. The next condition exits before another memory read.', 'completed=2; remaining=0; sum=17']
  ], 'The repeated instruction path works because each visit has a new, consistently interpreted state.'], ['Updating the pointer but forgetting the count', 'The address continues to move while the exit condition never approaches completion. Correct local arithmetic does not guarantee termination.'], 'What should initialization produce for an empty request? Sum zero and remaining zero, followed by an immediate exit with no element read.'),
  'while-shape': dive('Make the top test authorize each read', [
    'A top-tested loop places the permission check before the operation it protects. When CX means remaining elements, CX=0 forbids entering the body. This naturally handles an empty request and makes every executed load depend on a preceding nonzero count.',
    'In the checkpoint, CX is supplied by the lab and describes the request. The allocated array may contain more elements than this request asks to process. Replacing the incoming count with the storage capacity changes the interface and defeats the zero and short cases.'
  ], ['Use only the requested prefix', 'A buffer contains words 5, 13, 21, and 34, but the caller supplies CX=2.', [
    ['Accept the first body', 'The top test sees two remaining elements. Load the first word, add five, advance by two bytes, and decrement the count.', 'CX=1; sum=5; pointer=b+2'],
    ['Accept one more body', 'The next test sees one. Process thirteen and update the same state variables once.', 'CX=0; sum=18; pointer=b+4'],
    ['Reject the next read', 'The top test now sees zero and exits. The stored words 21 and 34 exist, but they are outside this request’s permitted prefix.', 'completed reads=2']
  ], 'Storage capacity limits what could be requested; the incoming count determines what this invocation should do.'], ['Reloading a familiar sample count inside the loop routine', 'That discards the caller’s argument. A routine that always processes four words cannot implement a request for zero or two words.'], 'If CX begins at zero, should SI need to point to a readable element for this loop body? No element access occurs on that path, though the surrounding interface may impose additional pointer requirements.'),
  'do-while': dive('Separate permission to enter from permission to repeat', [
    'A bottom-tested body runs at least once after entry. That makes it appropriate only when the first iteration is already justified. For arbitrary counts, an entry guard supplies that justification, while the bottom test decides whether another iteration remains.',
    'JCXZ and JNZ can participate in the same loop while reading different state. JCXZ directly checks CX under this address size. JNZ reads ZF from the preceding decrement. Keeping those dependencies distinct prevents an unrelated flag value from being mistaken for the entry condition.'
  ], ['Guard a body that consumes one word', 'Consider a body that loads a word, advances its pointer, then executes DEC CX and JNZ body.', [
    ['Check zero before entry', 'If CX is zero, JCXZ done bypasses the body. The first memory read is never attempted, satisfying an empty request.', 'initial CX=0 -> zero reads'],
    ['Trace a one-element request', 'With CX=1, the guard admits the body once. DEC changes one to zero, setting ZF so JNZ does not repeat.', 'initial CX=1 -> one read'],
    ['Explain the unguarded failure', 'Entering with zero performs an unjustified read before DEC wraps CX to FFFF. The bottom condition sees a nonzero count and repeats.', 'unguarded zero -> CX=FFFF after first body']
  ], 'The entry guard and bottom test solve different boundary questions and are both part of the algorithm.'], ['Calling the zero guard an optimization', 'Without it, the behavior changes: an empty request reads memory and enters a long count cycle. The guard is required for correctness under this contract.'], 'When could the entry guard be omitted legitimately? When the caller contract guarantees a positive count and the routine is only used under that proven precondition.'),
  'loop-instruction': dive('Expand LOOP mentally before trusting its compact spelling', [
    'With the course’s sixteen-bit address size, LOOP decrements CX and branches if the result is nonzero. It preserves arithmetic flags. The compact instruction combines a count update and a control decision, but it does not initialize the count or check whether entering the body was allowed.',
    'This distinction matters when the body produces flags needed afterward. Replacing LOOP with DEC CX and JNZ changes the flag behavior even when the iteration count matches. Check both the iteration count and every promised register or flag result before substituting one instruction sequence for another.'
  ], ['Trace a guarded three-iteration loop', 'Assume an entry guard has confirmed CX=3 before the first body.', [
    ['Finish the first body', 'LOOP decrements three to two and branches. Any arithmetic flags produced by the body remain as they were when LOOP was reached.', 'CX: 3 -> 2; repeat'],
    ['Finish the second body', 'The next LOOP decrements two to one and branches again. The pointer must already have advanced by exactly one element per completed body.', 'CX: 2 -> 1; repeat'],
    ['Finish the third body', 'One becomes zero, so control falls through. There were three body executions and three count updates.', 'CX: 1 -> 0; exit']
  ], 'The count trace explains the behavior without treating LOOP as a complete high-level loop construct.'], ['Entering a body with CX=0', 'A subsequent sixteen-bit LOOP wraps the count to FFFF. With no other exit, the conventional body sequence completes 65536 iterations for this zero-count input.'], 'Does BITS 16 mean LOOP always uses CX in every possible encoding? The address-size attribute selects the count width. These examples retain the ordinary sixteen-bit address size and its CX behavior.'),
  'for-index': dive('Relate completed count to remaining count', [
    'An index loop and a remaining-count loop can describe the same traversal from opposite directions. If N is the fixed length and k is the number completed, then remaining equals N-k. Choosing one interpretation consistently makes each condition and update easier to justify.',
    'An index also needs conversion into a byte displacement. You can keep a separate pointer synchronized with the index, or calculate the displacement when needed. In either design, the proof must connect the index’s element units to the pointer’s byte units.'
  ], ['Traverse a three-word prefix by index', 'Let N=3, index k begin at zero, and the pointer begin at b.', [
    ['Admit the first index', 'Unsigned k<N holds for zero, so the body reads the word at b. Afterward k becomes one and the pointer becomes b+2.', 'k=1; pointer=b+2; remaining=2'],
    ['Reach the last valid index', 'After two bodies, k=2 and the pointer is b+4. This is the final valid word because the length is three.', 'k=2 < N=3'],
    ['Exit at equality', 'After the third body, k=3 and the pointer is b+6. An unsigned above-or-equal rejection prevents using this one-past position as another element.', 'k=N -> exit']
  ], 'The index, remaining count, and pointer can all describe the same progress if their units and relationship stay explicit.'], ['Testing index greater than length', 'That admits index equal to length and causes one extra body. A zero-based array’s exclusive upper bound requires rejecting equality too.'], 'If the element size changes from two to four bytes, which relation changes? The pointer becomes b+4k, while k<N and remaining=N-k keep their element-count meaning.'),
  'invariant': dive('Prove initialization, preservation, and the exit meaning', [
    'An invariant is a statement that holds each time a chosen loop boundary is reached. The statement must cover every permitted input and every visit to that boundary. Show that initialization establishes it and that one permitted body preserves it. Then combine it with the exit condition to explain the final result.',
    'Termination needs an additional argument. A nonnegative remaining count that decreases on every admitted body cannot decrease forever. If one branch skips the decrement, the invariant may no longer describe progress, and a loop can stall even while its arithmetic operations remain individually valid.'
  ], ['Prove a prefix sum relationship', 'Let N=4 and let k count completed words. At the top, SI=b+2k, CX=N-k, and AX is the chosen-width sum of the first k words.', [
    ['Establish the base case', 'Initialization gives k=0, SI=b, CX=4, and AX=0. The sum of no elements is zero, so every part of the statement holds.', 'k=0 satisfies the invariant'],
    ['Preserve one step', 'If CX is positive, word k exists within the requested prefix. Adding it, advancing SI by two, and decrementing CX establishes the same statement for k+1.', 'one body: k -> k+1'],
    ['Use the exit condition', 'At CX=0, the relationship gives k=N. AX therefore contains the sum of exactly the requested words, with no further access justified.', 'CX=0 implies k=N']
  ], 'The invariant explains what the state means; the decreasing count explains why a final state is reached.'], ['Proving only that the count reaches zero', 'A loop can terminate after reading the wrong addresses. The pointer and accumulator relationships are necessary to prove what it computed.'], 'What must be added when the required sum is exact? A range argument that the accumulator cannot overflow, or a wider arithmetic design that preserves all required bits.'),
  'worked-trace': dive('Keep the final pointer distinct from a final access', [
    'A trace should include the state before each read and after each update. This shows which address actually supplied each element. A one-past pointer at exit is often the natural result of advancing after the final body; it is valid as a boundary value without authorizing another dereference.',
    'Use the caller’s requested count to determine how much of the allocated array this invocation processes. A prefix-sum routine can return different totals over the same storage. The count-controlled access sequence lets the routine handle each permitted prefix through the same mechanism.'
  ], ['Trace a three-word request', 'Words 7, 12, and 19 occupy six bytes starting at b. Begin with CX=3 and AX=0.', [
    ['After the first body', 'The read at b contributes seven. The update leaves SI=b+2, CX=2, and AX=7.', 'read b; next=b+2; remaining=2; sum=7'],
    ['After the second body', 'The read at b+2 contributes twelve. The sum becomes nineteen while the remaining count becomes one.', 'read b+2; next=b+4; remaining=1; sum=19'],
    ['After the third body', 'The read at b+4 contributes nineteen. The final sum is thirty-eight, hexadecimal 0026. SI=b+6 is held but never read because CX is now zero.', 'next=b+6; remaining=0; sum=38']
  ], 'The final total and the exact read sequence support different parts of the correctness claim.'], ['Adding a final load after the loop to inspect the pointer', 'That turns the harmless one-past boundary into an out-of-range access. Inspect the pointer value directly, keeping the memory-access count unchanged.'], 'For a supplied count of one over this same storage, what should the final state be? One read at b, sum seven, pointer b+2, and remaining count zero.'),
  'stride-bug': dive('Reconstruct the words selected by a faulty stride', [
    'A stride mismatch can produce a deterministic sum of unintended overlapping words. The processor still reads exactly the bytes its addresses specify. Expanding the array into bytes lets you reconstruct those wrong words and connect the final error to the pointer update.',
    'Changing the loop count or adding a correction constant cannot repair the underlying traversal. The body’s consumption width and the pointer’s advance must agree with the representation. Test multiple counts after changing the stride because an error may be invisible in the first iteration.'
  ], ['Explain a one-byte step through word data', 'The array contains 0x0102, 0x0304, and 0x0506, giving bytes 02 01 04 03 06 05.', [
    ['Read the first word', 'Both correct and faulty loops begin at offset zero and load 0102. A one-element test therefore cannot distinguish their pointer policies.', 'offset 0 -> 0102'],
    ['Read after the faulty update', 'Advancing by one reaches offset one and loads bytes 01 and 04, forming 0401. The second array element 0304 begins at offset two.', 'offset 1 -> 0401'],
    ['Compare the third read', 'Another one-byte step reaches offset two, loading 0304. The faulty loop has consumed overlapping views; the intended distinct elements begin at offsets zero, two, and four.', 'faulty reads: 0102, 0401, 0304']
  ], 'The unexpected values are evidence of specific address choices and can be predicted before running.'], ['Using all-zero high bytes as the only test data', 'Some patterns make incorrect overlapping reads less obvious. Distinct high and low bytes make the wrong grouping recognizable.'], 'Which smallest request reveals this particular stride error? Two elements, because the first read is identical and the second is the first affected by the update.'),
  'accumulator-overflow': dive('Place carry consumption before pointer arithmetic', [
    'A wider accumulator can be built from word pieces, but the loop must preserve the carry dependency between them. ADD to the low word produces CF, and ADC updates the high word. An intervening pointer ADD can replace CF and silently corrupt the total.',
    'Choose the width from the maximum permitted element count and value. For an exact unsigned sum, maximum count times maximum element gives a bound. A modulo sum has a different contract and may deliberately retain only the low word. State which result the routine promises before judging a wrapped display.'
  ], ['Accumulate a sum that needs a high word', 'Start DX:AX at zero and add word elements 50000 and 30000.', [
    ['Add the first element', '50000 fits in the low word, so AX becomes C350 and DX stays zero after the corresponding ADC.', 'DX:AX=0000:C350'],
    ['Add the second element', 'The full sum is 80000, hexadecimal 00013880. The low ADD retains 3880 with CF=1.', 'AX=3880; pending CF=1'],
    ['Consume carry before advancing', 'ADC DX, 0 makes DX one. Only after that may ADD SI, 2 safely replace the arithmetic flags used by the accumulation chain.', 'DX:AX=0001:3880']
  ], 'Arithmetic correctness and loop-update ordering meet at the shared carry flag.'], ['Advancing SI between low ADD and high ADC', 'The pointer addition’s carry then becomes the arithmetic input. The final total can be wrong even though the next memory address is correct.'], 'Would a word accumulator suffice for at most ten elements each no larger than 1000? Yes, the maximum exact sum is 10000, below 65536. The range bound justifies the narrower design.'),
  'counted-or-terminated': dive('Use bounds to authorize a load and a sentinel to classify it', [
    'A length and a sentinel answer different questions. Remaining capacity says whether another byte may be read. A zero terminator says whether a byte already read marks the end of the string. A bounded string loop must apply those questions in the right order.',
    'If the allowed region ends without a terminator, the routine should report exhaustion and return before another memory access. Finding an accidental zero later does not validate the original representation. The successful and exhausted paths should have distinct meanings.'
  ], ['Scan a bounded character region', 'The allowed region has three bytes containing R, S, and zero.', [
    ['Authorize and inspect the first byte', 'With three bytes remaining, the load is allowed. R is nonzero, so process it and reduce the readable remainder.', 'remaining=2; processed="R"'],
    ['Process the second character', 'The next allowed load yields S. After processing, one byte remains available for inspection.', 'remaining=1; processed="RS"'],
    ['Recognize successful termination', 'The third allowed load yields zero. Stop before printing it. If this byte had been T, the next bound check would report exhaustion without a fourth read.', 'zero found within the allowed region']
  ], 'The length guards memory safety while the sentinel defines content termination.'], ['Testing for zero only after printing', 'That requests output for the terminator and reverses the intended content rule. Inspect the loaded byte before treating it as a character.'], 'Can an empty zero-terminated string require a read? Yes. Its first byte is the terminator, which must be readable to recognize emptiness. A counted zero-length sequence can exit without reading any element.', flow('Bounded zero-terminated traversal', 'The bound check happens before every load, including the load that discovers a terminator.', [['bound','Readable bytes remain?','A count authorizes the next memory access.','decision'],['load','Load one byte','Advance the pointer and account for the consumed byte.'],['zero','Is the byte zero?','The sentinel marks successful content termination.','decision'],['emit','Process the character','Only nonzero bytes enter this body.'],['success','Return success','The terminator was found within the region.','terminal'],['exhaust','Return exhaustion','No more bytes may be read.','terminal']], [['bound','load','Yes'],['bound','exhaust','No'],['load','zero'],['zero','success','Yes'],['zero','emit','No'],['emit','bound']], 'The bound makes a missing terminator a reported failure at the end of the permitted region.')),
  'loop-proof': dive('Test traversal effects separately from the total', [
    'Two loops can produce the same total while reading different numbers of elements. An extra read of zero leaves the sum unchanged, and repeated equal elements can hide a wrong address. A review should therefore predict access count and pointer movement as well as the final accumulator.',
    'Combine small boundary cases with the invariant. Zero checks entry permission, one checks a single body and exit, and several checks repeated updates. None alone proves every path, but each distinguishes a particular class of defect and strengthens the general reasoning.'
  ], ['Build a review table for one loop', 'Use words 9, 16, and 25 and consider requests for zero, one, and three elements.', [
    ['Review the empty case', 'Expect zero reads, zero sum, and no pointer advance. Any memory operation here reveals that the entry test does not protect the body.', 'N=0: reads=0; offset=0; sum=0'],
    ['Review one element', 'Expect one read, two bytes of pointer advance, and sum nine. This checks that the exit happens after exactly one permitted body.', 'N=1: reads=1; offset=2; sum=9'],
    ['Review repeated work', 'Expect three reads, six bytes of advance, and sum fifty. The invariant should connect every intermediate count, pointer, and partial total.', 'N=3: reads=3; offset=6; sum=50']
  ], 'A useful loop report explains what was accessed, what was accumulated, and why another body was not executed.'], ['Using only the final display as a bounds test', 'An out-of-range zero can leave the display correct. The absence of a wrong total is not evidence that every read was permitted.'], 'What should happen if the requested count exceeds the allocated array length? A broader interface needs an explicit rejection or a proven caller precondition; the raw loop cannot infer hidden allocation bounds.')
};
